CREATE OR REPLACE FUNCTION "admin"."alternate_route_floor"("p_tag" "text", "p_resolution" "text", "p_quality" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO ''
    AS $$
declare
  k text := concat_ws('|', 'alternate', quote_nullable(p_tag), quote_nullable(p_resolution), quote_nullable(p_quality));
  hit jsonb := admin.stmt_memo(k);
  v jsonb;
begin
  if hit ? 'v' then return case when jsonb_typeof(hit->'v') = 'null' then null else hit->'v' end; end if;
  v := admin.alternate_route_floor_now(p_tag, p_resolution, p_quality);
  perform admin.stmt_memo_put(k, v);
  return v;
end $$;


ALTER FUNCTION "admin"."alternate_route_floor"("p_tag" "text", "p_resolution" "text", "p_quality" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "admin"."alternate_route_floor_now"("p_tag" "text", "p_resolution" "text", "p_quality" "text") RETURNS "jsonb"
    LANGUAGE "sql" STABLE
    SET "search_path" TO ''
    AS $$
  with route as (
    select p.adapter, p.capabilities, p.estimated_image_costs, admin.provider_list_priced(p) as listed
    from public.ai_providers p
    where p.module='image' and p.id::text||'/'||p.model=p_tag
      and p.resolutions @> array[public.canonical_resolution(p_resolution)] and p.capabilities<>'{}'::jsonb
      and public.canonical_resolution(p_resolution) in ('1k','2k','4k')
  ), measured as (
    select count(*) as n, percentile_cont(0.95) within group (order by g.cost_usd) as p95
    from public.generation_jobs g
    where g.provider=any((select admin.route_cost_tags(p_tag))::text[]) and g.inputs->>'resolution' = any(public.resolution_aliases(p_resolution))
      and g.inputs ? 'quality' and g.inputs->>'quality'=p_quality
      and g.created_at>=now()-interval '30 days' and g.status='succeeded' and g.cost_usd is not null
      and not (g.inputs ? 'input_slots')
  ), sources as (
    select r.listed, m.n,
      -- Through jsonb as admin_image_provider_pricing returns it, so the rounding is unchanged.
      case when m.n>=10 then (to_jsonb(m.p95) #>> '{}')::numeric end as p95,
      (r.estimated_image_costs->>public.canonical_resolution(p_resolution))::numeric as estimate,
      case when r.adapter='openrouter_images' and not r.listed
        and jsonb_typeof(r.capabilities->'catalogImageCosts'->public.canonical_resolution(p_resolution))='number'
        and (r.capabilities->'catalogImageCosts'->>public.canonical_resolution(p_resolution))::numeric > 0
        then (r.capabilities->'catalogImageCosts'->>public.canonical_resolution(p_resolution))::numeric end as catalog,
      case when r.listed then
        ((case when p_quality='medium' then '{"1k":0.055,"2k":0.095,"4k":0.135}'
                    else '{"1k":0.081,"2k":0.135,"4k":0.206}' end)::jsonb->>public.canonical_resolution(p_resolution))::numeric end as list
    from route r cross join measured m
  ), priced as (
    select listed, n, coalesce(p95,estimate,catalog,list) as usd,
      case when p95 is not null then 'p95' when estimate is not null then 'estimate'
           when catalog is not null then 'catalog' when list is not null then 'list' end as basis
    from sources
  ), budget as (
    select admin.template_floor_budget() as usd
  )
  select jsonb_build_object('usd',priced.usd,'basis',priced.basis,'samples',priced.n,
    'credits',case when priced.usd is not null and budget.usd>0 then greatest(
      ceil(priced.usd*1.10/budget.usd)::int,
      case when priced.listed then (case when p_quality='medium' then
        '{"1k":1,"2k":2,"4k":3}' else '{"1k":2,"2k":4,"4k":6}' end::jsonb->>public.canonical_resolution(p_resolution))::int else 0 end) end)
  from priced, budget
$$;


ALTER FUNCTION "admin"."alternate_route_floor_now"("p_tag" "text", "p_resolution" "text", "p_quality" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "admin"."alternate_route_meets_floor"("p_tag" "text", "p_resolution" "text", "p_quality" "text", "p_price" integer) RETURNS boolean
    LANGUAGE "sql" STABLE
    SET "search_path" TO ''
    AS $$
  select coalesce(p_price >= (admin.alternate_route_floor(p_tag,p_resolution,p_quality)->>'credits')::int, false)
$$;


ALTER FUNCTION "admin"."alternate_route_meets_floor"("p_tag" "text", "p_resolution" "text", "p_quality" "text", "p_price" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "admin"."apply_style_refs"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
declare
  pending jsonb := nullif(current_setting('shotviva.save_style_refs',true),'')::jsonb;
begin
  if pending->>'id' = new.template_id then new.style_refs := pending->'refs'; end if;
  if new.style_refs <> '[]' and not admin.valid_style_refs(new.template_id,new.style_refs) then
    raise exception 'INVALID_STYLE_REFS' using errcode = '23514';
  end if;
  if tg_op = 'UPDATE' and old.style_refs is distinct from new.style_refs then
    new.version := old.version + 1;
    new.updated_at := now();
  end if;
  return new;
end;
$$;


ALTER FUNCTION "admin"."apply_style_refs"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "admin"."apply_template_step"("p_actor" "uuid", "p_step" "jsonb") RETURNS "void"
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
declare
  v_id text := p_step->>'id';
  v_active boolean;
  v_assignment jsonb;
  v_series uuid;
  v_row public.template_series;
begin
  case p_step->>'op'
  when 'save_category' then
    perform public.admin_save_template_category(p_step->'category', (p_step->>'is_new')::boolean, p_actor);
  when 'move_category' then
    perform public.admin_move_template_category(p_step->>'key', p_step->>'from_parent', p_step->>'parent', p_step->>'before', p_actor);
  when 'save_reference_category' then
    perform public.admin_save_reference_category(p_actor, p_step->>'key', p_step->>'name_en', p_step->>'name_zh',
      p_step->>'parent', (p_step->>'is_new')::boolean);
  when 'move_reference_category' then
    perform public.admin_move_reference_category(p_actor, p_step->>'key', p_step->>'from_parent', p_step->>'parent', p_step->>'before');
  when 'save_template' then
    v_assignment := p_step->'assignment';
    -- A series named by slug, which may have been created earlier in this batch.
    if p_step ? 'series_slug' then
      select s.id into v_series from public.template_series s where s.slug = p_step->>'series_slug';
      if v_series is null then raise exception 'SERIES_NOT_FOUND'; end if;
      v_assignment := jsonb_set(v_assignment, '{series_id}', to_jsonb(v_series));
    end if;
    -- An absent style_refs key is SQL null: the stored references stay, as in the editor.
    perform public.admin_save_template_assignment(p_actor, p_step->'template', p_step->'prompt', v_assignment,
      (p_step->>'is_new')::boolean, (p_step->>'expected')::integer, null, p_step->'style_refs');
  when 'set_cover' then
    -- What applyCover writes once the converted files are in the public bucket.
    update public.templates t set
      cover_before_url = case when p_step ? 'before' then p_step->>'before' else t.cover_before_url end,
      cover_after_url = case when p_step ? 'after' then p_step->>'after' else t.cover_after_url end
      where t.id = v_id;
    if not found then raise exception 'TEMPLATE_NOT_FOUND'; end if;
    perform admin.template_apply_audit(p_actor, 'template_apply_cover', v_id, 'templates:apply: cover');
  when 'test_run_cover' then
    -- 「设为封面」 on a trial run of this template, never of another one.
    if not exists(select from public.admin_test_runs r where r.id = (p_step->>'run_id')::uuid and r.template_id = v_id) then
      raise exception 'TEST_RUN_NOT_FOUND';
    end if;
    perform public.admin_set_test_run_cover(p_actor, (p_step->>'run_id')::uuid, p_step->>'before', p_step->>'after', null);
    perform admin.template_apply_audit(p_actor, 'template_apply_cover', v_id, 'templates:apply: cover from trial run ' || (p_step->>'run_id'));
  when 'set_sale' then
    perform public.admin_set_template_sale(p_actor, v_id, (p_step->>'enabled')::boolean);
  when 'set_active' then
    -- The 上架 switch's update (setTemplatesActive); the table's triggers re-check the floor.
    v_active := (p_step->>'active')::boolean;
    if v_active is null then raise exception 'INVALID_INPUT'; end if;
    -- Unpublishing needs a reason, as on the admin page.
    if not v_active and nullif(btrim(p_step->>'reason'), '') is null then raise exception 'UNPUBLISH_REASON_REQUIRED'; end if;
    update public.templates t set is_active = v_active,
      featured_rank = case when v_active then t.featured_rank end
      where t.id = v_id;
    if not found then raise exception 'TEMPLATE_NOT_FOUND'; end if;
    perform admin.template_apply_audit(p_actor, 'template_apply_active', v_id,
      'templates:apply: ' || case when v_active then 'published' else 'unpublished: ' || btrim(p_step->>'reason') end);
  when 'save_series' then
    -- The file is the source of truth for a series it names (by slug): the revision is the row's
    -- own, read under the series lock in the admin function's lock order, so a save earlier in
    -- this batch (a member joining or leaving) is not mistaken for another admin's edit.
    perform pg_advisory_xact_lock_shared(hashtextextended('shotviva.category_tree',0));
    perform pg_advisory_xact_lock(hashtextextended('shotviva.template_series',0));
    select * into v_row from public.template_series s where s.slug = p_step->'fields'->>'slug';
    perform public.admin_save_template_series(v_row.id, case when v_row.id is not null then admin.template_series_revision(v_row) end,
      p_step->'fields',
      case when p_step ? 'members' then array(select jsonb_array_elements_text(p_step->'members'))
        else array(select t.id from public.templates t where t.series_id = v_row.id order by t.series_sort_order, t.id) end,
      p_actor, p_step->>'reason');
  when 'save_profile' then
    -- The profile that is not live (1441); the file is the source of truth, so the expected version
    -- is the row's own, read under the template lock the function takes.
    perform public.admin_save_template_profile(p_actor, v_id, p_step->>'profile', p_step->'prompt', p_step->>'quality',
      p_step->'credits_cost', array(select jsonb_array_elements_text(coalesce(p_step->'unpriced_resolutions','[]'::jsonb))),
      (select p.prompt_version from public.template_profiles p where p.template_id = v_id and p.profile = p_step->>'profile'));
  when 'switch_profile' then
    -- The admin's switch (1441), audited with the batch's reason.
    perform admin.switch_template_profile(p_actor, v_id, p_step->>'profile', 'templates:apply');
  else
    raise exception 'INVALID_INPUT';
  end case;
end $$;


ALTER FUNCTION "admin"."apply_template_step"("p_actor" "uuid", "p_step" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "admin"."archive_template_prompt_version"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  if tg_op='UPDATE' and new.version=old.version then return null; end if;
  -- A restore already has its immutable snapshot. All other writes insert a new PK.
  if new.version=nullif(current_setting('shotviva.restore_prompt_version',true),'')::integer then return null; end if;
  insert into public.template_prompt_versions(template_id,version,body,model_params,provider_id,provider_model,style_refs,created_at,profile)
    values (new.template_id,new.version,new.body,new.model_params,new.provider_id,
      (select model from public.ai_providers where id=new.provider_id),new.style_refs,new.updated_at,new.active_profile);
  return null;
end $$;


ALTER FUNCTION "admin"."archive_template_prompt_version"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "admin"."assert_catalog_checkout"("p_product" "text", "p_revision" integer, "p_net_cents" integer, "p_code_percent" integer DEFAULT NULL::integer) RETURNS "void"
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
declare v admin.catalog_product_versions; k text;
begin
  perform pg_advisory_xact_lock_shared(hashtextextended('shotviva.catalog.economics',0));
  select v0.* into strict v from admin.catalog_product_versions v0 where (product_id,revision)=(p_product,p_revision);
  select kind into strict k from admin.catalog_products where product_id=p_product and published_revision=p_revision;
  if not v.listed or p_net_cents is null or p_net_cents<=0 then raise exception 'CATALOG_OFFER_CHANGED'; end if;
  if p_code_percent is not null and (p_code_percent not between 1 and 90 or
      admin.catalog_code_conflict(array[p_product],p_code_percent,null,null,null,false) is not null)
    then raise exception 'CATALOG_CODE_FLOOR: %',p_product; end if;
  if (p_revision>2 or not exists(select from admin.product_terms_v2 where product_id=p_product))
      and admin.catalog_cost_ok(k,p_net_cents,v.credits) is not true then raise exception 'CATALOG_COST_FLOOR: %',p_product; end if;
end $$;


ALTER FUNCTION "admin"."assert_catalog_checkout"("p_product" "text", "p_revision" integer, "p_net_cents" integer, "p_code_percent" integer) OWNER TO "postgres";

