CREATE OR REPLACE FUNCTION "admin"."assert_template_reference_range"("p_id" "text") RETURNS "void"
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
declare
  v_images jsonb;
  v_count integer;
  v_provider uuid;
  v_min integer;
  v_max integer;
begin
  select t.fields->'images',coalesce(jsonb_array_length(tp.style_refs),0),tp.provider_id
    into v_images,v_count,v_provider from public.templates t
    left join public.template_prompts tp on tp.template_id=t.id where t.id=p_id and t.module='image';
  if not found then return; end if;
  -- Edits use the source work and never attach template style references.
  if p_id='edit' then v_count := 0; end if;
  select coalesce((p.capabilities->>'minReferences')::integer,0),
         coalesce((p.capabilities->>'maxReferences')::integer,case when p.adapter='openai_images' then 4 end)
    into v_min,v_max from public.ai_providers p where p.module='image'
      and (p.id=v_provider or (v_provider is null and p.is_active)) for share;
  if not found then v_min:=0; v_max:=4; end if;
  -- A legacy OpenRouter row without a catalog snapshot still supports legacy saves.
  -- Configuring private images requires a known upper bound as in 0941.
  if (v_count > 0 and v_max is null)
     or coalesce((v_images->>'min')::integer,case when v_count>0 then 0 end) + v_count < v_min
     or coalesce((v_images->>'max')::integer,case when v_count>0 then 0 end) + v_count > v_max then
    raise exception 'MODEL_REFERENCE_LIMIT' using detail=format(
      '模型支持 %s–%s 张输入图，模板设置为 %s–%s 张用户照片，加上 %s 张画风参考图',
      v_min,coalesce(v_max::text,'未知'),v_images->>'min',v_images->>'max',v_count);
  end if;
end;
$$;


ALTER FUNCTION "admin"."assert_template_reference_range"("p_id" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "admin"."assert_template_sale_floor"("t" "public"."templates") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  bound uuid;
  route_tag text;
  supported text[];
  approved jsonb;
  tier text;
  budget numeric;
  usd numeric;
  openai_min jsonb;
  openai_usd jsonb;
  env_p95 jsonb;
begin
  if exists(select from public.template_sale_approvals s where s.template_id=t.id and s.unpriced_resolutions @> array['1k','2k','4k']) then
    raise exception 'TEMPLATE_PRICE_BELOW_FLOOR' using detail='请先为至少一个可售档位定价'; end if;
  select provider_id into bound from public.template_prompts where template_id=t.id for share;
  -- Keep model selection and its configured estimate stable through this commit.
  select p.id,p.id::text||'/'||p.model,admin.sale_route_resolutions(p) into bound,route_tag,supported
    from public.ai_providers p where p.module='image' and (p.id=bound or (bound is null and p.is_active)) for share;
  if bound is not null and cardinality(supported)=0 then
    raise exception 'TEMPLATE_PRICE_BELOW_FLOOR' using detail='所选模型的可用档位尚未确认'; end if;
  approved := admin.template_approved_prices(bound)->t.id;

  -- With no database provider the server uses its OpenAI environment model. SQL cannot
  -- see that setting. Take the highest eligible model p95 per tier in that case, at the
  -- template's own quality (1295).
  if bound is null then
    budget := admin.template_floor_budget();
    select jsonb_object_agg(r, cost) into env_p95 from (
      select r, max(p95) cost from (
        select provider, public.canonical_resolution(coalesce(inputs->>'resolution','1k')) r,
          percentile_cont(0.95) within group (order by cost_usd) p95
        from public.generation_jobs where provider like 'env/%' and status='succeeded'
          and cost_usd is not null and created_at >= now()-interval '30 days'
          and inputs ? 'quality' and inputs->>'quality'=t.quality and not (inputs ? 'input_slots')
        group by 1,2 having count(*)>=10
      ) per_model group by r
    ) per_tier;
  end if;
  if t.quality='medium' then
    openai_min := '{"1k":1,"2k":2,"4k":3}'; openai_usd := '{"1k":0.055,"2k":0.095,"4k":0.135}';
  else
    openai_min := '{"1k":2,"2k":4,"4k":6}'; openai_usd := '{"1k":0.081,"2k":0.135,"4k":0.206}';
  end if;
  foreach tier in array array['1k','2k','4k'] loop
    if exists(select from public.template_sale_approvals s where s.template_id=t.id and tier=any(s.unpriced_resolutions)) then continue; end if;
    if approved->>'quality'=t.quality and approved->'costs'->tier=t.credits_cost->tier then continue; end if;
    -- T96 never sells unsupported resolutions on this model. Those fields keep
    -- their existing positive placeholder; fallback reservations have their own check.
    if bound is not null then
      if not (tier=any(supported)) or coalesce((t.credits_cost->>tier)::int>=admin.slot_floor_credits(t,route_tag,tier,(admin.alternate_route_floor(route_tag,tier,t.quality)->>'credits')::int),false)
          then continue; end if;
    else
      usd := coalesce((env_p95->>tier)::numeric,(openai_usd->>tier)::numeric);
      if budget>0 and (t.credits_cost->>tier)::int >= admin.slot_floor_credits(t,'env/unknown',tier,greatest(ceil(usd*1.10/budget),(openai_min->>tier)::int)::int)
          then continue; end if;
    end if;
    raise exception 'TEMPLATE_PRICE_BELOW_FLOOR' using detail=format('模板 %s 的 %s 售价低于模型成本下限或缺少报价，请刷新报价后再保存。',t.id,tier);
  end loop;
end;
$$;


ALTER FUNCTION "admin"."assert_template_sale_floor"("t" "public"."templates") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "admin"."assign_template_prompt_version"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare wanted integer := nullif(current_setting('shotviva.restore_prompt_version',true),'')::integer;
  h public.template_prompt_versions%rowtype; latest integer;
begin
  -- Runs after both legacy BEFORE triggers, once their resolved refs and version bump are known.
  if tg_op='UPDATE' then
    if wanted is not null then
      select * into strict h from public.template_prompt_versions where template_id=new.template_id and version=wanted;
      if h.profile<>new.active_profile then raise exception 'VERSION_OTHER_PROFILE'; end if;
      if (h.body,h.model_params,h.provider_id,h.style_refs) is not distinct from
         (new.body,new.model_params,new.provider_id,new.style_refs) then
        new.version:=wanted; new.updated_at:=now(); return new;
      end if;
    end if;
    if new.version=old.version and new.provider_id is not distinct from old.provider_id then return new; end if;
  end if;
  select greatest(
    (select max(version) from public.template_prompt_versions where template_id=new.template_id),
    (select max(version) from admin.deleted_prompt_versions where template_id=new.template_id)
  ) into latest;
  new.version:=coalesce(latest+1,new.version); new.updated_at:=now();
  return new;
end $$;


ALTER FUNCTION "admin"."assign_template_prompt_version"() OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."ai_providers" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "module" "text" DEFAULT 'image'::"text" NOT NULL,
    "adapter" "text" NOT NULL,
    "label" "text" NOT NULL,
    "base_url" "text" DEFAULT 'https://api.openai.com/v1'::"text" NOT NULL,
    "model" "text" NOT NULL,
    "api_key_last4" "text",
    "is_active" boolean DEFAULT false NOT NULL,
    "notes" "text",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_by" "uuid",
    "vault_secret_id" "uuid",
    "price_input_text_per_m" numeric(12,6),
    "price_input_image_per_m" numeric(12,6),
    "price_output_per_m" numeric(12,6),
    "resolutions" "text"[] DEFAULT '{1k,2k,4k}'::"text"[] NOT NULL,
    "capabilities" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "estimated_image_costs" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "extra_input_image_usd" numeric,
    "byok_list_price" boolean DEFAULT true NOT NULL,
    "catalog_price" "jsonb",
    "list_price" "jsonb",
    CONSTRAINT "ai_providers_adapter_check" CHECK (("adapter" = ANY (ARRAY['openai_images'::"text", 'openrouter_images'::"text", 'ark_images'::"text", 'openai_responses'::"text"]))),
    CONSTRAINT "ai_providers_api_key_last4_check" CHECK ((("char_length"("api_key_last4") >= 1) AND ("char_length"("api_key_last4") <= 4))),
    CONSTRAINT "ai_providers_base_url_check" CHECK ((("base_url" ~ '^https://[^\s/?#@]+(/[^\s?#]*)?$'::"text") AND ("char_length"("base_url") <= 300))),
    CONSTRAINT "ai_providers_capabilities_check" CHECK (("jsonb_typeof"("capabilities") = 'object'::"text")),
    CONSTRAINT "ai_providers_catalog_price_check" CHECK ((("catalog_price" IS NULL) OR ("jsonb_typeof"("catalog_price") = 'object'::"text"))),
    CONSTRAINT "ai_providers_estimated_image_costs_check" CHECK ((("jsonb_typeof"("estimated_image_costs") = 'object'::"text") AND (("estimated_image_costs" - ARRAY['1k'::"text", '2k'::"text", '4k'::"text"]) = '{}'::"jsonb") AND (NOT "jsonb_path_exists"("estimated_image_costs", '$.*?(@.type() != "number" || @ <= 0)'::"jsonpath")))),
    CONSTRAINT "ai_providers_extra_input_image_usd_check" CHECK ((("extra_input_image_usd" IS NULL) OR (("extra_input_image_usd" >= (0)::numeric) AND ("extra_input_image_usd" < (10)::numeric)))),
    CONSTRAINT "ai_providers_key_pair" CHECK ((("vault_secret_id" IS NULL) = ("api_key_last4" IS NULL))),
    CONSTRAINT "ai_providers_label_check" CHECK ((("char_length"("label") >= 1) AND ("char_length"("label") <= 80))),
    CONSTRAINT "ai_providers_list_price_check" CHECK ((("list_price" IS NULL) OR ("jsonb_typeof"("list_price") = 'object'::"text"))),
    CONSTRAINT "ai_providers_model_check" CHECK ((("char_length"("model") >= 1) AND ("char_length"("model") <= 120))),
    CONSTRAINT "ai_providers_module_adapter" CHECK (((("module" = 'image'::"text") AND ("adapter" = ANY (ARRAY['openai_images'::"text", 'openrouter_images'::"text", 'ark_images'::"text"]))) OR (("module" = ANY (ARRAY['decision'::"text", 'dish_read'::"text"])) AND ("adapter" = 'openai_responses'::"text")))),
    CONSTRAINT "ai_providers_module_check" CHECK (("module" = ANY (ARRAY['image'::"text", 'decision'::"text", 'dish_read'::"text"]))),
    CONSTRAINT "ai_providers_notes_check" CHECK ((("notes" IS NULL) OR ("char_length"("notes") <= 500))),
    CONSTRAINT "ai_providers_prices_nonnegative" CHECK (((COALESCE("price_input_text_per_m", (0)::numeric) >= (0)::numeric) AND (COALESCE("price_input_image_per_m", (0)::numeric) >= (0)::numeric) AND (COALESCE("price_output_per_m", (0)::numeric) >= (0)::numeric))),
    CONSTRAINT "ai_providers_resolutions_check" CHECK ((("cardinality"("resolutions") > 0) AND ("array_ndims"("resolutions") = 1) AND ("resolutions" <@ ARRAY['1k'::"text", '2k'::"text", '4k'::"text"])))
);


