CREATE OR REPLACE FUNCTION "admin"."refresh_template_floor_budget"() RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare b numeric;
begin
  perform pg_advisory_xact_lock(hashtextextended('shotviva.template_floor_budget_cache', 0));
  b := admin.template_breakeven_budget_now();
  insert into admin.template_floor_budget_cache as c (singleton, breakeven, floor_budget, margin_target_bp, refreshed_at)
  values (true, b, coalesce(b, admin.lowest_credit_price()*0.761*0.4),
    case when b is not null then (select (s.value->>'margin_bp')::int from public.system_settings s where s.key='catalog_economics_policy') end,
    clock_timestamp())
  on conflict (singleton) do update set breakeven=excluded.breakeven, floor_budget=excluded.floor_budget,
    margin_target_bp=excluded.margin_target_bp, refreshed_at=excluded.refreshed_at;
  perform set_config('shotviva.stmt_memo', gen_random_uuid()::text, true);
end $$;


ALTER FUNCTION "admin"."refresh_template_floor_budget"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "admin"."relabel_seedream_rebind"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare target text := admin.provider_profile(new.provider_id);
begin
  if new.template_id='edit' and new.provider_id is distinct from old.provider_id and target<>new.active_profile then
    delete from public.template_profiles where template_id='edit' and profile=target;
    update public.template_profiles set profile=target, updated_at=now() where template_id='edit' and profile=new.active_profile;
    update public.template_prompt_versions set profile=target where template_id='edit';
    new.active_profile := target;
    return new;
  end if;
  if new.provider_id is distinct from old.provider_id
     and old.active_profile='openai' and new.active_profile='openai'
     and target='seedream'
     and admin.is_seedream_route(old.provider_id)
     and not exists(select from public.template_profiles where template_id=new.template_id and profile='seedream') then
    update public.template_profiles set profile='seedream', updated_at=now()
      where template_id=new.template_id and profile='openai';
    update public.template_prompt_versions v set profile='seedream'
      where v.template_id=new.template_id and v.profile='openai' and admin.is_seedream_route(v.provider_id);
    new.active_profile := 'seedream';
  end if;
  return new;
end $$;


ALTER FUNCTION "admin"."relabel_seedream_rebind"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "admin"."remove_unpublished_series_members"() RETURNS integer
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
declare
  r record;
  v_series uuid[] := '{}';
  v_removed integer := 0;
begin
  -- Same lock order as the series save and the T93 sync: category tree shared, series, rows.
  perform pg_advisory_xact_lock_shared(hashtextextended('shotviva.category_tree', 0));
  perform pg_advisory_xact_lock(hashtextextended('shotviva.template_series', 0));
  for r in
    select t.id, t.series_id, s.slug from public.templates t join public.template_series s on s.id = t.series_id
    where not t.is_active or t.deleted_at is not null
    order by s.slug, t.series_sort_order, t.id
    for update of t
  loop
    raise notice 'auto: unpublished: template % left series %', r.id, r.slug;
    update public.templates set series_id = null, series_sort_order = 0 where id = r.id;
    if not r.series_id = any(v_series) then v_series := v_series || r.series_id; end if;
    v_removed := v_removed + 1;
  end loop;
  -- Only the series a member just left: their remaining members become 1, 2, 3… in current order.
  update public.templates t set series_sort_order = n.ord
    from (select id, row_number() over (partition by series_id order by series_sort_order, id)::integer as ord
          from public.templates where series_id = any(v_series)) n
    where t.id = n.id and t.series_sort_order <> n.ord;
  return v_removed;
end $$;


ALTER FUNCTION "admin"."remove_unpublished_series_members"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "admin"."renewal_terms"("p_v2" boolean, "p_user_id" "uuid", "p_product_id" "text", "p_invoice_id" "text", "p_period_end" timestamp with time zone, "p_amount_total" integer, "p_currency" "text", "p_amount_tax" integer, "p_method" "text", "p_charge_id" "text" DEFAULT NULL::"text") RETURNS "public"."credit_change"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_product public.products;
  v_change public.credit_change;
  v_key text := 'renewal:' || p_invoice_id;
  v_org uuid;
begin
  perform pg_advisory_xact_lock_shared(hashtextextended('shotviva.template_catalog',0));
  if p_invoice_id is null or p_invoice_id not like 'in\_%' then
    raise exception 'INVALID_INPUT' using detail = 'invoice id is required';
  end if;
  if p_period_end is null then
    raise exception 'INVALID_INPUT' using detail = 'period end is required';
  end if;
  if p_amount_total is null or p_amount_tax is null or p_currency is null or p_method is null then
    raise exception 'INVALID_INPUT' using detail = 'payment fields are all required';
  end if;

  -- 2033: an active org's main admin's renewal credits go to the org pool. The org row first.
  v_org := public._org_purchase_pool(p_user_id, v_key);

  -- Only memberships renew; packs are always one-time.
  v_product := admin.catalog_settlement_product(p_v2,p_user_id,p_product_id,v_key);
  if v_product.days is null then raise exception 'PRODUCT_NOT_FOUND'; end if;

  v_change := public._apply_credit_change(
    p_user_id, 'paid', 'purchase', v_product.credits, 'renewal ' || v_product.id,
    v_key, null, v_product.id, null
  );
  if not v_change.applied then
    return v_change;
  end if;

  update public.profiles
     set paid_until = greatest(paid_until, p_period_end)
   where id = p_user_id
  returning paid_until into v_change.paid_until;

  -- The row was inserted just above in this transaction; record where paid_until landed, as
  -- membership purchases do.
  update public.credit_ledger
     set paid_until_after = v_change.paid_until
   where idempotency_key = v_key;

  if v_org is not null then
    v_change.credits := public._org_purchase_deposit(v_org, p_user_id, v_key, v_product.credits);
  end if;

  insert into public.payments
    (user_id, product_id, channel, stripe_invoice_id, stripe_charge_id,
     amount_total, amount_tax, currency, method)
  values
    (p_user_id, p_product_id, 'stripe', p_invoice_id, p_charge_id,
     p_amount_total, p_amount_tax, lower(p_currency), p_method);

  return v_change;
end;
$$;


ALTER FUNCTION "admin"."renewal_terms"("p_v2" boolean, "p_user_id" "uuid", "p_product_id" "text", "p_invoice_id" "text", "p_period_end" timestamp with time zone, "p_amount_total" integer, "p_currency" "text", "p_amount_tax" integer, "p_method" "text", "p_charge_id" "text") OWNER TO "postgres";


