CREATE OR REPLACE FUNCTION "admin"."reservation_route_allowed"("t" "public"."templates", "route" "text", "tier" "text", "price" integer, "fallback" boolean, "v2" boolean) RETURNS boolean
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO ''
    AS $$
begin
  if fallback or exists (
    select from public.template_prompts tp join public.ai_providers p on p.id=tp.provider_id
    where tp.template_id=t.id and route is distinct from p.id::text||'/'||p.model
  ) then
    if not coalesce(price>=admin.slot_floor_credits(t,route,tier,admin.fallback_route_floor(route,tier,t.quality)::int),false) then return false; end if;
  end if;
  if v2 and exists (
    select from admin.template_price_snapshots s join admin.template_price_batches b on b.id=s.batch_id
    join admin.template_tariffs_v2 c on c.id=s.template_id
    where b.reverted_at is null and s.template_id=t.id and c.quality=t.quality
      and c.costs->tier=t.credits_cost->tier
  ) and admin.template_approved_price((select p.id from public.ai_providers p where p.module='image'
      and p.id::text=split_part(route,'/',1) and p.id::text||'/'||p.model=route), t.id) is null
  then return coalesce(price>=admin.slot_floor_credits(t,route,tier,(admin.alternate_route_floor(route,tier,t.quality)->>'credits')::int),false); end if;
  return true;
end $$;


ALTER FUNCTION "admin"."reservation_route_allowed"("t" "public"."templates", "route" "text", "tier" "text", "price" integer, "fallback" boolean, "v2" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "admin"."reserve_prompt_lab_budget"("p_total" numeric) RETURNS "void"
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
declare budget jsonb;
begin
  if p_total is null or p_total<=0 or p_total>=10000 then raise exception 'INVALID_INPUT'; end if;
  perform pg_advisory_xact_lock(hashtext('shotviva.admin_test_budget'));
  budget:=public.admin_test_budget_status();
  if (budget->>'spent_usd')::numeric+p_total>(budget->>'budget_usd')::numeric then raise exception 'TEST_BUDGET_EXCEEDED'; end if;
end $$;


ALTER FUNCTION "admin"."reserve_prompt_lab_budget"("p_total" numeric) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "admin"."restore_approved_wallets_v2"() RETURNS "void"
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
declare rec record; batch admin.pricing_wallet_cutover;
begin
  perform pg_advisory_xact_lock(hashtextextended('shotviva.template_catalog',0));
  lock table public.profiles, public.generation_jobs, public.credit_ledger, public.payments, public.subscriptions in share row exclusive mode;
  select * into strict batch from admin.pricing_wallet_cutover where version='v2';
  if batch.rolled_back_at is not null then return; end if;
  if (select coalesce(max(id),0) from public.credit_ledger)<>batch.last_ledger_after or
     exists(select from public.profiles where created_at >= batch.started_at) or
     exists(select from public.payments where created_at >= batch.started_at) or
     exists(select from public.generation_jobs where created_at >= batch.started_at or status='running') then
    raise exception 'ECONOMIC_ACTIVITY_AFTER_CUTOVER';
  end if;
  for rec in select * from jsonb_to_recordset(batch.waived_refunds) as x(id bigint,"before" integer,"after" integer) loop
    update public.payments set clawback_shortfall=rec.before where id=rec.id and clawback_shortfall=rec.after and status='refunded';
    if not found then raise exception 'REFUND_CHANGED_AFTER_CUTOVER'; end if;
  end loop;
  for rec in select user_id,pool,delta from public.credit_ledger where idempotency_key like 'pricing:v2:close:%' order by id loop
    perform public.admin_adjust_credits(rec.user_id,-rec.delta,'Pricing rollback restores legacy balance',rec.pool,'pricing:v2:restore:'||rec.pool||':'||rec.user_id);
  end loop;
  if admin.wallet_digest_v2()<>batch.digest_before then raise exception 'RESTORED_WALLET_MISMATCH'; end if;
  update admin.pricing_wallet_cutover set rolled_back_at=clock_timestamp() where version='v2';
end;
$$;


ALTER FUNCTION "admin"."restore_approved_wallets_v2"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "admin"."rollback_template_price_catalog_v2"() RETURNS "void"
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
declare batch bigint; problems text;
begin
  perform pg_advisory_xact_lock(hashtextextended('shotviva.template_catalog',0));
  select id into batch from admin.template_price_batches where reverted_at is null for update;
  if not found then return; end if;
  lock table public.templates in share row exclusive mode nowait;
  if exists (select 1 from public.generation_jobs g where g.inputs->>'pricing_catalog_version'='v2') then
    raise exception 'TEMPLATE_CATALOG_HAS_NEW_JOBS';
  end if;
  select string_agg(s.template_id,', ' order by s.template_id) into problems from admin.template_price_snapshots s
    left join public.templates t on t.id=s.template_id
    where s.batch_id=batch and (t.id is null or admin.template_price_state(t) is distinct from s.applied);
  if problems is not null then raise exception 'TEMPLATE_CATALOG_CHANGED: %',problems; end if;
  update admin.template_price_batches set reverted_at=clock_timestamp() where id=batch;
  update public.templates t set quality=s.previous->>'quality',credits_cost=s.previous->'costs',
    is_active=(s.previous->>'active')::boolean,featured_rank=(s.previous->>'featured')::smallint
    from admin.template_price_snapshots s where s.batch_id=batch and s.template_id=t.id;
end;
$$;


ALTER FUNCTION "admin"."rollback_template_price_catalog_v2"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "admin"."route_cost_tags"("p_tag" "text") RETURNS "text"[]
    LANGUAGE "sql" STABLE
    SET "search_path" TO ''
    AS $$
  with me as (
    select admin.provider_cost_model(p) as m from public.ai_providers p
      where p.module='image' and p.id::text=split_part(p_tag,'/',1) and p.id::text||'/'||p.model=p_tag
    union all select substr(p_tag, length('env/')+1) where p_tag like 'env/_%'
  )
  select array(select distinct tag from (
    select p_tag as tag
    union all select p.id::text||'/'||p.model from public.ai_providers p, me
      where me.m is not null and p.module='image' and admin.provider_cost_model(p)=me.m
    union all select 'env/'||me.m from me where me.m is not null
  ) pool order by tag)
$$;


ALTER FUNCTION "admin"."route_cost_tags"("p_tag" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "admin"."route_p95_by_quality"("p_tag" "text") RETURNS "jsonb"
    LANGUAGE "sql" STABLE
    SET "search_path" TO ''
    AS $$
  select coalesce(jsonb_object_agg(quality,tiers),'{}'::jsonb) from (
    select quality,jsonb_object_agg(res,cost) tiers from (
      -- Jobs before PR-2 say 3k for the same tier as 4k: one sample set.
      select g.inputs->>'quality' quality, public.canonical_resolution(g.inputs->>'resolution') res,
        percentile_cont(0.95) within group (order by g.cost_usd) cost
      from public.generation_jobs g
      where g.provider=any((select admin.route_cost_tags(p_tag))::text[]) and g.inputs ? 'quality' and g.inputs->>'quality' in ('medium','high')
        and g.inputs->>'resolution' in ('1k','2k','3k','4k')
        and g.created_at>=now()-interval '30 days' and g.status='succeeded' and g.cost_usd is not null
        and not (g.inputs ? 'input_slots')
      group by 1,2 having count(*)>=10
    ) per_tier group by quality
  ) per_quality
$$;


ALTER FUNCTION "admin"."route_p95_by_quality"("p_tag" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "admin"."route_slot_costs"("p_tag" "text") RETURNS "jsonb"
    LANGUAGE "sql" STABLE
    SET "search_path" TO ''
    AS $$
  select jsonb_build_object(
    'extra_input_usd', (select p.extra_input_image_usd from public.ai_providers p
      where p.module='image' and p.id::text=split_part(p_tag,'/',1) and p.id::text||'/'||p.model=p_tag),
    'p95_full', coalesce((select jsonb_object_agg(quality,tiers) from (
      select quality, jsonb_object_agg(res,slots) tiers from (
        select quality, res, jsonb_object_agg(n::text,cost) slots from (
          -- Jobs before PR-2 say 3k for the same tier as 4k: one sample set.
          select g.inputs->>'quality' quality, public.canonical_resolution(g.inputs->>'resolution') res, admin.slot_count(g.inputs) n,
            percentile_cont(0.95) within group (order by g.cost_usd) cost
          from public.generation_jobs g
          where g.provider=any((select admin.route_cost_tags(p_tag))::text[]) and g.inputs->>'quality' in ('medium','high') and g.inputs->>'resolution' in ('1k','2k','3k','4k')
            and g.status='succeeded' and g.cost_usd is not null and g.created_at>=now()-interval '30 days'
            and admin.slot_count(g.inputs) between 2 and 8
          group by 1,2,3 having count(*)>=10
        ) per_n group by quality, res
      ) per_res group by quality
    ) per_quality),'{}'::jsonb))
$$;


ALTER FUNCTION "admin"."route_slot_costs"("p_tag" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "admin"."sale_floor_hidden"() RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  m record; t public.templates; sale public.template_sale_approvals; p public.ai_providers;
  route text; reason text; floor jsonb; result jsonb:='[]'::jsonb;
begin
  for m in select pm.id from admin.published_web_members pm order by pm.id loop
    if admin.web_standard_sale_allowed(m.id) then continue; end if;
    select * into t from public.templates where id=m.id;
    select * into sale from public.template_sale_approvals where template_id=m.id;
    route:=null; floor:=null; p:=null;
    select a.id::text||'/'||a.model into route from public.ai_providers a where a.module='image' and
      a.id=coalesce((select tp.provider_id from public.template_prompts tp where tp.template_id=t.id and t.id<>'edit'),
                    (select b.id from public.ai_providers b where b.module='image' and b.is_active));
    if not coalesce(sale.enabled,false) then reason:='sale_closed';
    elsif '1k'=any(sale.unpriced_resolutions) then reason:='unpriced';
    elsif route is null then reason:='no_route';
    else
      select * into p from public.ai_providers a where a.module='image' and a.id::text||'/'||a.model=route;
      if not ('1k'=any(admin.sale_route_resolutions(p))) then reason:='route_unsupported';
      else reason:='below_floor'; floor:=admin.alternate_route_floor(route,'1k',t.quality);
        -- A slot template's floor (slot_floor_credits); report the floor its price is held to.
        if admin.slot_floor_factor(t)>1 then
          floor:=floor||jsonb_build_object('slots',admin.slot_floor_factor(t),'credits',admin.slot_floor_credits(t,route,'1k',(floor->>'credits')::int));
        end if;
      end if;
    end if;
    result:=result||jsonb_build_array(jsonb_build_object('template_id',t.id,'quality',t.quality,
      'price',(t.credits_cost->>'1k')::int,'route',route,'reason',reason,'floor',floor));
  end loop;
  return result;
end $$;


ALTER FUNCTION "admin"."sale_floor_hidden"() OWNER TO "postgres";


