    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
begin
  if old.status = 'removed' and new.status = 'active' then
    new.promo_allowance := 0;
    new.held_promo_credits := 0;
    new.paid_allowance_custom := null;
    new.promo_allowance_custom := null;
  end if;
  return new;
end;
$$;


