CREATE OR REPLACE FUNCTION "public"."affiliate_partner_referrals"("p_user" "uuid", "p_before_at" timestamp with time zone DEFAULT NULL::timestamp with time zone, "p_before_id" "text" DEFAULT NULL::"text") RETURNS TABLE("masked_hash" "text", "referred_at" timestamp with time zone, "payment_count" bigint, "commission_amount" bigint)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  with page as (
    select c.id,c.referred_at,encode(sha256(convert_to(c.id::text,'UTF8')),'hex') masked_hash
    from public.profiles c where c.referred_by=p_user and (p_before_at is null or
      (c.referred_at,encode(sha256(convert_to(c.id::text,'UTF8')),'hex'))<(p_before_at,p_before_id))
    order by c.referred_at desc,masked_hash desc limit 31
  ) select pg.masked_hash,pg.referred_at,count(p.id),coalesce(sum(c.amount),0)::bigint from page pg
    left join public.payments p on p.user_id=pg.id
    left join public.affiliate_commissions c on c.payment_id=p.id and c.level=1 and c.affiliate_user_id=p_user
    group by pg.masked_hash,pg.referred_at order by pg.referred_at desc,pg.masked_hash desc;
$$;


ALTER FUNCTION "public"."affiliate_partner_referrals"("p_user" "uuid", "p_before_at" timestamp with time zone, "p_before_id" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."affiliate_partner_summary"("p_user" "uuid") RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  with settings as (
    select s.settlement_day,(now() at time zone 'UTC')::date today from public.affiliate_settings s where s.singleton
  ), dates as (
    select today, (date_trunc('month',today)::date+(settlement_day-1)) this_settlement from settings
  ), period as (
    select today,case when this_settlement>today then this_settlement else (this_settlement+interval '1 month')::date end next_day from dates
  )
  select jsonb_build_object(
    'clicks',(select coalesce(sum(clicks),0) from public.affiliate_click_days where affiliate_user_id=p_user and day between t.today-29 and t.today),
    'referred',r.referred,'paidUsers',r.paid_users,'pending',b.pending,'available',b.available,'paid',b.paid,
    'maturing',(select coalesce(sum(amount),0) from public.affiliate_commissions where affiliate_user_id=p_user and status='pending'
      and (confirm_after at time zone 'UTC')::date<=t.next_day),
    'nextSettlement',t.next_day)
  from public.affiliate_balances b cross join period t cross join lateral (
    select count(*) referred,count(*) filter(where exists(select from public.payments p where p.user_id=c.id)) paid_users
      from public.profiles c where c.referred_by=p_user
  ) r where b.affiliate_user_id=p_user;
$$;


ALTER FUNCTION "public"."affiliate_partner_summary"("p_user" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."affiliate_payout_fee_quote"("p_rules" "jsonb", "p_gross" bigint) RETURNS "jsonb"
    LANGUAGE "plpgsql" IMMUTABLE
    SET "search_path" TO ''
    AS $$
declare r jsonb; v_left bigint:=p_gross; v_fee bigint; v_lines jsonb:='[]'::jsonb;
begin
  if p_gross is null or p_gross<0 or (p_rules is not null and jsonb_typeof(p_rules)<>'array') then
    raise exception 'INVALID_INPUT'; end if;
  for r in select e.value from jsonb_array_elements(coalesce(p_rules,'[]'::jsonb)) with ordinality e(value,n) order by e.n loop
    v_fee:=div(p_gross::numeric*coalesce((r->>'percent_bp')::integer,0)+5000,10000)::bigint
      +coalesce((r->>'fixed_cents')::bigint,0);
    if r->>'min_cents' is not null then v_fee:=greatest(v_fee,(r->>'min_cents')::bigint); end if;
    if r->>'max_cents' is not null then v_fee:=least(v_fee,(r->>'max_cents')::bigint); end if;
    v_fee:=least(greatest(v_fee,0),v_left);
    v_left:=v_left-v_fee;
    v_lines:=v_lines||jsonb_build_array(r||jsonb_build_object('amount',v_fee));
  end loop;
  return jsonb_build_object('gross',p_gross,'fees',p_gross-v_left,'net',v_left,'lines',v_lines);
end;
$$;


ALTER FUNCTION "public"."affiliate_payout_fee_quote"("p_rules" "jsonb", "p_gross" bigint) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."affiliate_payout_fee_rules_for"("p_program" "text", "p_method" "text", "p_at" timestamp with time zone) RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select coalesce(jsonb_agg(public._affiliate_fee_rule_json(r) order by r.sort_order,r.id),'[]'::jsonb)
    from public.affiliate_payout_fee_rules r
   where r.program=p_program and r.active and r.effective_from<=p_at
     and (r.payout_methods is null or p_method=any(r.payout_methods));
$$;


ALTER FUNCTION "public"."affiliate_payout_fee_rules_for"("p_program" "text", "p_method" "text", "p_at" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."affiliate_payout_fees"("p" "public"."affiliate_payouts") RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select case
    when p.status='paid' then jsonb_build_object('gross',coalesce(p.paid_amount,p.amount),'fees',coalesce(p.fee_amount,0),
      'net',coalesce(p.paid_amount,p.amount)-coalesce(p.fee_amount,0),'lines',coalesce(p.fee_lines,'[]'::jsonb))
    when p.status in ('due','held') then
      public.affiliate_payout_fee_quote(p.fee_rules,coalesce(public.affiliate_payout_payable(p),p.amount))
  end;
$$;


ALTER FUNCTION "public"."affiliate_payout_fees"("p" "public"."affiliate_payouts") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."affiliate_payout_payable"("p" "public"."affiliate_payouts") RETURNS bigint
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select case when p.status in ('due','held') and not p.legacy_review_required then
    least(public._affiliate_linked_payable(p),greatest(0,b.confirmed-b.paid
      + (select coalesce(sum(j.amount),0) from public.affiliate_adjustments j where j.affiliate_user_id=p.affiliate_user_id)
      - (select coalesce(sum(case when o.legacy_review_required then o.amount else public._affiliate_linked_payable(o) end),0)
         from public.affiliate_payouts o where o.affiliate_user_id=p.affiliate_user_id and o.id<>p.id and o.status in ('due','held'))))::bigint
    end from public.affiliate_balances b where b.affiliate_user_id=p.affiliate_user_id;
$$;


ALTER FUNCTION "public"."affiliate_payout_payable"("p" "public"."affiliate_payouts") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."affiliate_recompute_payment"("p_payment_id" bigint, "p_new_payment" boolean DEFAULT false) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_payment public.payments; v_enabled boolean; v_open boolean; v_lost boolean; v_snapshot jsonb;
  v_exists boolean; v_retry boolean; v_missing boolean;
begin
  if p_payment_id is null then return; end if;
  select enabled into strict v_enabled from public.affiliate_settings where singleton;
  if p_new_payment and not v_enabled then return; end if;
  select exists(select from public.affiliate_commissions c where c.payment_id=p_payment_id) into v_exists;
  select e.snapshot into v_snapshot from public.affiliate_recompute_errors e where e.payment_id=p_payment_id and e.resolved_at is null;
  v_retry:=found;
  if not (v_exists or v_retry or (p_new_payment and v_enabled)) then return; end if;
  -- Serializes manual/cron retries with the existing billing transaction on this payment.
  select p.* into strict v_payment from public.payments p where p.id=p_payment_id for update;
  if v_payment.amount_total=0 then return; end if;
  if v_retry then v_snapshot:=public._affiliate_snapshot_remap(v_snapshot); end if;
  if not v_exists and v_snapshot is null then v_snapshot:=public._affiliate_snapshot(v_payment); end if;
  if not v_exists and v_snapshot is null then
    if v_retry then update public.affiliate_recompute_errors set resolved_at=now() where payment_id=p_payment_id and resolved_at is null; end if;
    return;
  end if;
  if v_payment.currency <> 'usd' then raise exception 'AFFILIATE_NON_USD_PAYMENT'; end if;
  select is_open,is_lost into strict v_open,v_lost from public._affiliate_dispute_state(v_payment);
  perform public._affiliate_write_commission(v_payment,v_snapshot,1::smallint,v_open,v_lost);
  perform public._affiliate_write_commission(v_payment,v_snapshot,2::smallint,v_open,v_lost);
  update public.affiliate_recompute_errors set resolved_at=now() where payment_id=p_payment_id and resolved_at is null;
  v_missing:=public._affiliate_fee_missing(v_payment);
  if v_missing and exists(select from public.affiliate_commissions c where c.payment_id=p_payment_id and c.status='confirmed') then
    perform public._affiliate_fee_alert_open(v_payment);
  elsif not v_missing then
    update public.affiliate_fee_alerts set resolved_at=now() where payment_id=p_payment_id and resolved_at is null;
  end if;
exception when others or query_canceled or assert_failure then
  -- Retain no sensitive exception DETAIL/CONTEXT (it can contain an entire failed row).
  begin
    insert into public.affiliate_recompute_errors(payment_id,error,snapshot)
      values(p_payment_id,sqlstate || ': ' || left(sqlerrm,300),v_snapshot)
      on conflict(payment_id) where resolved_at is null do update set error=excluded.error,
        snapshot=coalesce(affiliate_recompute_errors.snapshot,excluded.snapshot);
  exception when others or query_canceled or assert_failure then
    -- Even an unavailable error sink must never undo a successful payment/credit write.
    return;
  end;
end;
$$;


ALTER FUNCTION "public"."affiliate_recompute_payment"("p_payment_id" bigint, "p_new_payment" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."affiliate_save_profile"("p_user" "uuid", "p_payout_method" "text", "p_payout_details" "text", "p_us_person" boolean, "p_terms_version" "text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_version text;
begin
  select terms_version into strict v_version from public.affiliate_settings where singleton and enabled for share;
  if p_terms_version is not null and p_terms_version is distinct from v_version then raise exception 'AFFILIATE_TERMS_CHANGED'; end if;
  if (p_payout_method is null) <> (nullif(trim(p_payout_details),'') is null) then raise exception 'INVALID_INPUT'; end if;
  update public.affiliates set payout_method=p_payout_method,payout_details=nullif(trim(p_payout_details),''),
    us_person=p_us_person,terms_version=v_version,
    terms_accepted_at=case when terms_version is distinct from v_version then now() else coalesce(terms_accepted_at,now()) end
    where user_id=p_user and status='active'
      -- A maintenance-only save requires consent already recorded for the locked current version.
      and (p_terms_version is not null or (terms_version=v_version and terms_accepted_at is not null));
  if not found then raise exception 'AFFILIATE_NOT_FOUND'; end if;
end;
$$;


ALTER FUNCTION "public"."affiliate_save_profile"("p_user" "uuid", "p_payout_method" "text", "p_payout_details" "text", "p_us_person" boolean, "p_terms_version" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."affiliate_signup_ref_store"("p_user" "uuid", "p_slug" "text") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
begin
  if p_user is null then return false; end if;
  delete from public.affiliate_signup_refs where user_id = p_user;
  if p_slug is null or p_slug !~ '^[a-z0-9-]{3,24}$' then return false; end if;
  perform 1 from auth.users u
   where u.id = p_user and u.email_confirmed_at is null and u.phone_confirmed_at is null
     and u.last_sign_in_at is null and u.created_at >= now() - interval '10 minutes';
  if not found then return false; end if;
  insert into public.affiliate_signup_refs (user_id, slug) values (p_user, p_slug);
  return true;
end;
$_$;


ALTER FUNCTION "public"."affiliate_signup_ref_store"("p_user" "uuid", "p_slug" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."affiliate_signup_ref_take"("p_user" "uuid") RETURNS "text"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_slug text; v_at timestamptz;
begin
  delete from public.affiliate_signup_refs where user_id = p_user returning slug, created_at into v_slug, v_at;
  if v_slug is null or v_at < now() - interval '1 day' then return null; end if;
  perform 1 from auth.users u
   where u.id = p_user and u.confirmation_sent_at <= v_at
     and (u.recovery_sent_at is null or u.recovery_sent_at < v_at)
     and (u.email_change_sent_at is null or u.email_change_sent_at < v_at)
     and not exists (select 1 from auth.identities i where i.user_id = p_user and i.provider <> 'email');
  if not found then return null; end if;
  return v_slug;
end;
$$;


ALTER FUNCTION "public"."affiliate_signup_ref_take"("p_user" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."apply_payment_code_effects"("p_user" "uuid", "p_payment_id" bigint, "p_code_id" "uuid", "p_amount_discount" integer, "p_inviter_credits" integer, "p_inviter_cap" integer) RETURNS "jsonb"
    LANGUAGE "sql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select public.apply_payment_code_effects(p_user, p_payment_id, p_code_id, p_amount_discount,
    p_inviter_credits, p_inviter_cap,
    (select s.value::text::integer from public.system_settings s where s.key = 'code_inviter_window_days'));
$$;


ALTER FUNCTION "public"."apply_payment_code_effects"("p_user" "uuid", "p_payment_id" bigint, "p_code_id" "uuid", "p_amount_discount" integer, "p_inviter_credits" integer, "p_inviter_cap" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."apply_payment_code_effects"("p_user" "uuid", "p_payment_id" bigint, "p_code_id" "uuid", "p_amount_discount" integer, "p_inviter_credits" integer, "p_inviter_cap" integer, "p_reward_window_days" integer) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$

declare
  v_payment record;
  v_invite record;
  v_discount record;
  v_conflict boolean := false;
  v_rewarded boolean := false;
  v_reward_time timestamptz;
  reward_credits integer;
begin
  if p_amount_discount is null or p_amount_discount < 0 or (p_code_id is null and p_amount_discount <> 0)
     or p_inviter_cap is null or p_inviter_cap <= 0
     or p_reward_window_days is null or p_reward_window_days <= 0 then
    raise exception 'INVALID_INPUT';
  end if;

  -- T71 takes the payment lock before any balance locks. Keep that order for refund races.
  select product_id, channel, stripe_session_id, code_id, amount_discount, code_effects_applied_at,
         code_discount_conflict into v_payment
    from public.payments where id = p_payment_id and user_id = p_user for no key update;
  if not found then raise exception 'PAYMENT_NOT_FOUND'; end if;
  if v_payment.code_effects_applied_at is not null then
    if v_payment.code_id is distinct from p_code_id or v_payment.amount_discount <> p_amount_discount then
      raise exception 'IDEMPOTENCY_CONFLICT';
    end if;
    return jsonb_build_object('applied', false, 'rewarded', false, 'conflict', v_payment.code_discount_conflict);
  end if;
  if (v_payment.channel = 'waffo' and p_code_id is not null)
     or (v_payment.channel = 'stripe' and v_payment.stripe_session_id is null) then
    raise exception 'INVALID_INPUT';
  end if;

  -- A user cannot acquire a new invitation after payment. Lock both profiles in canonical
  -- order for reciprocal invites and serialize all rewards for a given inviter.
  select id, inviter_user_id, inviter_rewarded_at, org_invite into v_invite from public.code_redemptions
    where user_id = p_user and kind = 'invite' and status = 'ok';
  perform 1 from public.profiles where id in (p_user, v_invite.inviter_user_id)
    order by id for no key update;

  if p_code_id is not null then
    select r.id, r.discount_used_payment_id into v_discount from public.code_redemptions r
      join public.codes c on c.id = r.code_id
     where r.code_id = p_code_id and r.user_id = p_user and r.status = 'ok'
       and v_payment.product_id = any(c.discount_products);
    if not found then raise exception 'PAYMENT_CODE_MISMATCH'; end if;
    v_conflict := v_discount.discount_used_payment_id is not null and v_discount.discount_used_payment_id <> p_payment_id;
    if not v_conflict then
      update public.code_redemptions set discount_used_payment_id = p_payment_id,
             checkout_token = null, checkout_expires_at = null, checkout_prepared = false where id = v_discount.id;
    end if;
  end if;

  v_reward_time := clock_timestamp();
  if v_invite.inviter_user_id is not null then
    select (value->>'inviterCredits')::integer into strict reward_credits from public.system_settings where key = 'code_invite_rewards';
  end if;
  if reward_credits > 0 and v_invite.inviter_rewarded_at is null
     -- 2032: no personal inviter reward for an org staff member's code: the org earns through
     -- commissions. Marked at redemption since 2032; an earlier one is known by its org_l1
     -- binding to that staff member.
     and not coalesce(v_invite.org_invite, false)
     and not public._in_active_org(v_invite.inviter_user_id)
     and not exists (select 1 from public.profiles c where c.id = p_user
                      and c.referred_source = 'org_l1' and c.referred_member = v_invite.inviter_user_id)
     and not exists (select 1 from public.payments where user_id = p_user and id < p_payment_id)
     and exists (select 1 from public.profiles where id = v_invite.inviter_user_id and banned_at is null)
     -- Rewards survive the invitee deleting their profile and redemption.
     and (select count(*) from public.credit_ledger where user_id = v_invite.inviter_user_id
           and kind = 'invite_reward' and created_at > v_reward_time - make_interval(days => p_reward_window_days)) < p_inviter_cap then
    -- The reward has no membership product/days and never changes current_tier.
    v_rewarded := (public._apply_credit_change(v_invite.inviter_user_id, 'paid', 'invite_reward',
                    reward_credits, '邀请首付奖励', 'invite:' || v_invite.id)).applied;
    update public.code_redemptions set inviter_rewarded_at = v_reward_time, inviter_reward_payment_id = p_payment_id
      where id = v_invite.id;
  end if;
  update public.payments set code_id = p_code_id, amount_discount = p_amount_discount,
         code_discount_conflict = v_conflict, code_effects_applied_at = clock_timestamp()
    where id = p_payment_id;
  return jsonb_build_object('applied', true, 'rewarded', v_rewarded, 'conflict', v_conflict)
    || case when v_rewarded then jsonb_build_object('reward_credits', reward_credits, 'inviter_id', v_invite.inviter_user_id) else '{}'::jsonb end;
end;
$$;


ALTER FUNCTION "public"."apply_payment_code_effects"("p_user" "uuid", "p_payment_id" bigint, "p_code_id" "uuid", "p_amount_discount" integer, "p_inviter_credits" integer, "p_inviter_cap" integer, "p_reward_window_days" integer) OWNER TO "postgres";


