CREATE OR REPLACE FUNCTION "public"."archive_org_works"("p_user_id" "uuid") RETURNS TABLE("job_id" "uuid", "credit_pool" "text", "source_key" "text", "archive_key" "text")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
#variable_conflict use_column
begin
  -- An org's primary admin cannot go: orgs.owner_user_id would block deleting the account after
  -- its files were gone. Refused before anything happens; the org's admin is changed first.
  if exists (select 1 from public.orgs o where o.owner_user_id = p_user_id) then
    raise exception 'ORG_OWNER_CANNOT_DELETE_ACCOUNT';
  end if;
  -- An org work still being made would land in outputs/<user>/ after its copy was taken. A row
  -- left running past the sweeper's day (sweep_stale_generation_jobs) is dead and not waited for.
  if exists (select 1 from public.generation_jobs j where j.user_id = p_user_id and j.org_id is not null
              and j.status = 'running' and j.created_at > now() - interval '24 hours') then
    raise exception 'JOB_RUNNING';
  end if;
  -- A row from an earlier, unfinished try whose work has since been deleted is dropped.
  delete from public.org_work_archive a
   using public.generation_jobs j
   where j.id = a.job_id and j.user_id = p_user_id and a.reason = 'account_deleted' and a.deleted_at is null
     and (j.deleted_at is not null or j.status <> 'succeeded');
  -- No creator id outlives the account, the audit of earlier deletes included.
  update public.org_work_deletions set maker_user_id = null where maker_user_id = p_user_id;
  insert into public.org_work_archive (job_id, org_id, template_id, credit_pool, aspect_ratio, output_key, made_at, reason)
  select j.id, j.org_id, j.template_id, j.credit_pool, j.inputs ->> 'aspect_ratio',
         'org-works/' || j.org_id::text || '/' || j.id::text || coalesce(substring(j.output_key from '\.[a-z0-9]{2,5}$'), '.png'),
         j.created_at, 'account_deleted'
    from public.generation_jobs j
   where j.user_id = p_user_id and j.org_id is not null and j.status = 'succeeded' and j.deleted_at is null
     and j.output_key is not null
  on conflict (job_id) do nothing;
  return query
    select a.job_id, a.credit_pool, j.output_key, a.output_key
      from public.org_work_archive a
      join public.generation_jobs j on j.id = a.job_id
     where j.user_id = p_user_id and a.reason = 'account_deleted' and a.deleted_at is null
       and j.status = 'succeeded' and j.deleted_at is null and a.copied_at is null
     order by a.made_at, a.job_id;
end;
$_$;


ALTER FUNCTION "public"."archive_org_works"("p_user_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."attach_catalog_session"("p_user" "uuid", "p_token" "uuid", "p_session" "text", "p_url" "text") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  update admin.catalog_checkout_attempts set session_id=p_session,session_url=p_url,
    params=(params #- '{metadata,buyer_ip}') #- '{metadata,buyer_ua}'
    where token=p_token and user_id=p_user and (session_id is null or session_id=p_session);
  if not found then raise exception 'IDEMPOTENCY_CONFLICT'; end if;
  return true;
end
$$;


ALTER FUNCTION "public"."attach_catalog_session"("p_user" "uuid", "p_token" "uuid", "p_session" "text", "p_url" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."attach_ticket_images"("p_ticket_id" "uuid", "p_owner_id" "uuid", "p_message_id" "uuid", "p_images" "jsonb") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_prefix text := 'tickets/' || p_owner_id::text || '/' || p_ticket_id::text || '/';
  v_image jsonb;
begin
  if p_images is null or jsonb_typeof(p_images) = 'null' then
    return;
  end if;
  if jsonb_typeof(p_images) <> 'array' then
    raise exception 'INVALID_INPUT' using detail = 'images must be a list';
  end if;
  if jsonb_array_length(p_images) > 3 then
    raise exception 'INVALID_INPUT' using detail = 'at most 3 images per message';
  end if;

  for v_image in select value from jsonb_array_elements(p_images) loop
    if jsonb_typeof(v_image) <> 'object' or left(coalesce(v_image ->> 'object_key', ''), char_length(v_prefix)) <> v_prefix then
      raise exception 'INVALID_INPUT' using detail = 'image is not under this ticket';
    end if;
    begin
      insert into public.support_ticket_attachments (message_id, ticket_id, object_key, content_type, bytes, width, height)
      values (
        p_message_id,
        p_ticket_id,
        v_image ->> 'object_key',
        v_image ->> 'content_type',
        (v_image ->> 'bytes')::integer,
        (v_image ->> 'width')::integer,
        (v_image ->> 'height')::integer
      );
    exception
      when check_violation or not_null_violation or unique_violation
        or invalid_text_representation or numeric_value_out_of_range then
        raise exception 'INVALID_INPUT' using detail = 'image entry is invalid';
    end;
  end loop;
end;
$$;


ALTER FUNCTION "public"."attach_ticket_images"("p_ticket_id" "uuid", "p_owner_id" "uuid", "p_message_id" "uuid", "p_images" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."begin_identity_judge"("p_user_id" "uuid", "p_text_hash" "text", "p_per_hour" integer) RETURNS "jsonb"
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
declare
  v_cached boolean;
  v_id bigint;
begin
  if p_user_id is null or p_per_hour is null or p_per_hour < 1 then
    raise exception 'INVALID_INPUT' using detail = 'user and a positive hourly limit are required';
  end if;
  perform pg_advisory_xact_lock(hashtextextended('identity_judge:' || p_user_id::text, 0));

  if p_text_hash is not null then
    select c.identity_swap into v_cached
      from public.identity_judge_calls c
     where c.user_id = p_user_id and c.text_hash = p_text_hash and c.identity_swap is not null
       and c.created_at > now() - interval '10 minutes'
     order by c.created_at desc
     limit 1;
    if found then
      return jsonb_build_object('status', 'cached', 'identity_swap', v_cached);
    end if;
  end if;

  if (select count(*) from public.identity_judge_calls c
       where c.user_id = p_user_id and c.created_at > now() - interval '1 hour') >= p_per_hour then
    return jsonb_build_object('status', 'limited');
  end if;

  insert into public.identity_judge_calls (user_id, text_hash) values (p_user_id, p_text_hash)
  returning id into v_id;

  delete from public.identity_judge_calls c
   where c.id in (select o.id from public.identity_judge_calls o
                   where o.created_at < now() - interval '1 day'
                   order by o.created_at
                   limit 500);
  return jsonb_build_object('status', 'call', 'id', v_id);
end;
$$;


ALTER FUNCTION "public"."begin_identity_judge"("p_user_id" "uuid", "p_text_hash" "text", "p_per_hour" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."bump_template_prompt_version"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
begin
  if new.body is distinct from old.body or new.model_params is distinct from old.model_params
      or new.version = old.version + 1 then
    new.version := old.version + 1;
    new.updated_at := now();
  else
    new.version := old.version;
  end if;
  return new;
end;
$$;


ALTER FUNCTION "public"."bump_template_prompt_version"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."canonical_resolution"("p" "text") RETURNS "text"
    LANGUAGE "sql" IMMUTABLE PARALLEL SAFE
    SET "search_path" TO ''
    AS $$
  select case when p in ('3k','4k') then '4k' else p end
$$;


ALTER FUNCTION "public"."canonical_resolution"("p" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."canonical_tier_array"("p" "text"[]) RETURNS "text"[]
    LANGUAGE "sql" IMMUTABLE PARALLEL SAFE
    SET "search_path" TO ''
    AS $$
  select case when p is null then null else coalesce(array(
    select r from (select public.canonical_resolution(x) r, min(i) i from unnest(p) with ordinality u(x,i) group by 1) s order by i
  ), '{}') end
$$;


ALTER FUNCTION "public"."canonical_tier_array"("p" "text"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."canonical_tiers"("p" "jsonb", "p_tier_field" boolean DEFAULT false) RETURNS "jsonb"
    LANGUAGE "plpgsql" IMMUTABLE PARALLEL SAFE
    SET "search_path" TO ''
    AS $$
declare
  k text; v jsonb; out jsonb;
  tier_fields constant text[] := array['resolution','resolutions','unpriced_resolutions','unpricedResolutions','resolutionLimit'];
begin
  if p is null then return null; end if;
  case jsonb_typeof(p)
    when 'object' then
      out := '{}';
      for k, v in select * from jsonb_each(p) loop
        out := out || jsonb_build_object(case when k = '3k' and not p ? '4k' then '4k' else k end, public.canonical_tiers(v, k = any(tier_fields)));
      end loop;
      return out;
    when 'array' then
      return coalesce((select jsonb_agg(public.canonical_tiers(e, p_tier_field) order by i) from jsonb_array_elements(p) with ordinality a(e,i)), '[]');
    when 'string' then
      return case when p_tier_field then to_jsonb(public.canonical_resolution(p #>> '{}')) else p end;
    else
      return p;
  end case;
end;
$$;


ALTER FUNCTION "public"."canonical_tiers"("p" "jsonb", "p_tier_field" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."catalog_channel_price"("p_product" "text", "p_revision" integer, "p_channel" "text", "p_key" "text", "p_recurring" boolean, "p_store" "text" DEFAULT NULL::"text", "p_mode" "text" DEFAULT NULL::"text") RETURNS "text"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_id text;
begin
  if p_channel='stripe' then
    select price_id into v_id from admin.catalog_stripe_prices
      where product_id=p_product and revision=p_revision and lookup_key=p_key;
    if v_id is null and (p_revision<>2 or not exists(select from admin.product_terms_v2 where product_id=p_product)
        or exists(select from admin.catalog_stripe_prices where product_id=p_product and revision=p_revision)) then
      raise exception 'CATALOG_CHANNEL_UNVERIFIED';
    end if;
  elsif p_channel='waffo' then
    select case when p_recurring then b.recurring_id else b.one_time_id end into v_id
      from admin.catalog_waffo_bindings b join admin.catalog_product_versions v using(product_id,revision)
      where b.product_id=p_product and b.revision=p_revision and b.store_id=p_store and b.mode=p_mode
        and b.usd_cents=v.usd_cents;
    if v_id is null then raise exception 'CATALOG_CHANNEL_UNVERIFIED'; end if;
  else raise exception 'INVALID_INPUT';
  end if;
  return v_id;
end
$$;


ALTER FUNCTION "public"."catalog_channel_price"("p_product" "text", "p_revision" integer, "p_channel" "text", "p_key" "text", "p_recurring" boolean, "p_store" "text", "p_mode" "text") OWNER TO "postgres";


