CREATE OR REPLACE FUNCTION "public"."checkout_discount"("p_user" "uuid", "p_product_id" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$

declare
  v_now timestamptz := clock_timestamp();
begin
  -- 2032 (Owner 2026-11-28): an active org member, the primary admin included, uses no discount
  -- code while a member, not even one redeemed before joining.
  if public._in_active_org(p_user) then return null; end if;
  return (
    select jsonb_build_object('code_id', c.id, 'code', c.code, 'stripe_coupon_id', c.stripe_coupon_id,
                              'percent', c.discount_percent, 'redemption_id', r.id)
      from public.code_redemptions r
      join public.codes c on c.id = r.code_id
     where r.user_id = p_user and r.status = 'ok'
       and r.discount_used_payment_id is null and r.discount_void_at is null
       and (r.discount_expires_at is null or r.discount_expires_at > v_now)
       and c.active and (c.starts_at is null or c.starts_at <= v_now)
       and (c.expires_at is null or c.expires_at > v_now)
       and c.stripe_coupon_id is not null and p_product_id = any(c.discount_products)
  );
end;
$$;


ALTER FUNCTION "public"."checkout_discount"("p_user" "uuid", "p_product_id" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."claim_batch_zip"("p_user_id" "uuid", "p_batch_id" "uuid", "p_token" "uuid") RETURNS "text"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  state admin.batch_zip_requests;
  at_time timestamptz;
  recent timestamptz[];
  active jsonb;
  result text := 'acquired';
begin
  if not (public.effective_limits(p_user_id)->>'batch_zip')::boolean then return 'upgrade'; end if;
  insert into admin.batch_zip_requests (user_id) values (p_user_id) on conflict do nothing;
  select * into strict state from admin.batch_zip_requests where user_id=p_user_id for update;
  at_time := clock_timestamp();
  recent := array(select t from unnest(state.request_times) t where t > at_time - interval '1 minute');
  if cardinality(recent) >= 3 then return 'limited'; end if;
  select coalesce(jsonb_object_agg(key,value), '{}') into active from jsonb_each(state.active_batches)
    where (value->>'expires')::timestamptz > at_time;
  if active ? p_batch_id::text then
    result := 'packing';
  else
    active := active || jsonb_build_object(p_batch_id::text,
      jsonb_build_object('token', p_token, 'expires', at_time + interval '6 minutes'));
  end if;
  update admin.batch_zip_requests set request_times = array_append(recent,at_time), active_batches = active where user_id=p_user_id;
  return result;
end;
$$;


ALTER FUNCTION "public"."claim_batch_zip"("p_user_id" "uuid", "p_batch_id" "uuid", "p_token" "uuid") OWNER TO "postgres";


