CREATE OR REPLACE FUNCTION "public"."hook_before_user_created"("event" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_user jsonb := event->'user';
  v_provider text := v_user->'app_metadata'->>'provider';
  v_email text := lower(trim(coalesce(v_user->>'email', '')));
  v_phone text := regexp_replace(coalesce(v_user->>'phone', ''), '[^0-9]', '', 'g');
  v_refused jsonb := jsonb_build_object('error', jsonb_build_object(
    'http_code', 403, 'message', 'Please sign up on the website.'));
begin
  if v_provider = 'email' then
    if v_email = '' or not exists (
         select 1 from public.signup_requests r
          where r.email_key = encode(sha256(convert_to(v_email, 'UTF8')), 'hex')
            and r.requested_at > now() - interval '10 minutes') then
      return v_refused;
    end if;
  elsif v_provider = 'phone' then
    if v_phone = '' or not exists (
         select 1 from public.sms_sends s
          where s.phone_key = encode(sha256(convert_to(v_phone, 'UTF8')), 'hex')
            and s.requested_at > now() - interval '10 minutes') then
      return v_refused;
    end if;
  end if;
  return '{}'::jsonb;
end;
$$;


ALTER FUNCTION "public"."hook_before_user_created"("event" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."list_my_wish_notices"("p_user_id" "uuid") RETURNS TABLE("request_id" "uuid", "template_id" "text", "template_name_en" "text", "template_name_zh" "text", "description_excerpt" "text", "is_author" boolean)
    LANGUAGE "sql" STABLE
    SET "search_path" TO ''
    AS $$
  select n.request_id, t.id, t.name, coalesce(nullif(t.translations #>> '{zh,name}', ''), t.name),
         left(r.description, 40), r.user_id = n.user_id
    from public.template_request_notices n
    join public.template_requests r on r.id = n.request_id
    join public.templates t on t.id = r.template_id
   where n.user_id = p_user_id and n.seen_at is null
     and t.is_active and 'web' = any(t.visible_in)
     and exists (select 1 from public.system_settings where key = 'wishlist_enabled' and value = 'true'::jsonb)
   order by n.created_at desc, n.request_id desc
   limit 5;
$$;


ALTER FUNCTION "public"."list_my_wish_notices"("p_user_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."list_work_shares"("p_user_id" "uuid", "p_limit" integer DEFAULT 30, "p_before_at" timestamp with time zone DEFAULT NULL::timestamp with time zone, "p_before_id" "text" DEFAULT NULL::"text") RETURNS TABLE("id" "text", "title" "text", "show_before" boolean, "created_at" timestamp with time zone, "revoked_at" timestamp with time zone, "works" integer, "cover_job_id" "uuid")
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select s.id, s.title, s.show_before, s.created_at, s.revoked_at, live.works, live.cover
    from public.work_shares s
    cross join lateral (
      select count(*)::integer as works, (array_agg(j.id order by k.ord))[1] as cover
        from unnest(s.job_ids) with ordinality as k(job_id, ord)
        join public.generation_jobs j on j.id = k.job_id
       where j.user_id = s.user_id and j.status = 'succeeded' and j.deleted_at is null and j.moderation_status <> 'rejected'
         and j.org_access_ended_at is null
    ) live
   where s.user_id = p_user_id
     and (p_before_at is null or (s.created_at, s.id) < (p_before_at, p_before_id))
   order by s.created_at desc, s.id desc
   limit least(greatest(coalesce(p_limit, 30), 1), 100);
$$;


ALTER FUNCTION "public"."list_work_shares"("p_user_id" "uuid", "p_limit" integer, "p_before_at" timestamp with time zone, "p_before_id" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."lock_catalog_checkout"("p_user" "uuid", "p_token" "uuid", "p_hash" "text", "p_product" "text", "p_revision" integer, "p_channel" "text", "p_key" "text", "p_price" "text", "p_unit" integer, "p_net" integer, "p_percent" integer, "p_method" "text", "p_form" "text", "p_params" "jsonb", "p_store" "text" DEFAULT NULL::"text", "p_mode" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v admin.catalog_product_versions;
  v_bound text;
  v_retry jsonb;
  v_expiry timestamptz;
begin
  perform pg_advisory_xact_lock(hashtextextended(p_token::text,0));
  v_retry := public.resume_catalog_checkout(p_user,p_token,p_hash,p_channel);
  if v_retry is not null then return v_retry; end if;
  perform pg_advisory_xact_lock_shared(hashtextextended('shotviva.catalog.economics',0));
  perform 1 from public.system_settings where key='pricing_catalog_version' and value='"v2"' for share;
  if not found then raise exception 'CODE_CHECKOUT_OFFER_CHANGED'; end if;
  select ver.* into v from admin.catalog_products p join admin.catalog_product_versions ver
    on (p.product_id,p.published_revision)=(ver.product_id,ver.revision)
    where p.product_id=p_product and p.published_revision=p_revision and ver.listed for share of p;
  if not found then raise exception 'CODE_CHECKOUT_OFFER_CHANGED'; end if;
  v_bound := public.catalog_channel_price(p_product,p_revision,p_channel,p_key,p_form='subscription',p_store,p_mode);
  if v_bound is not null and v_bound<>p_price then raise exception 'CODE_CHECKOUT_OFFER_CHANGED'; end if;
  if p_unit<=0 or p_net<=0 or p_unit>v.usd_cents or p_net>p_unit then raise exception 'INVALID_INPUT'; end if;
  perform admin.catalog_buyer_terms(p_user,p_product,v.usd_cents,p_token,p_channel,p_unit,p_net,p_percent,p_params);
  perform admin.assert_catalog_checkout(p_product,p_revision,p_net,p_percent);
  v_expiry := case when p_channel='stripe' then to_timestamp((p_params->>'expires_at')::bigint)
    else now()+interval '30 minutes' end;
  insert into admin.catalog_checkout_attempts(token,user_id,product_id,revision,channel,request_hash,price_id,
    unit_cents,net_cents,credits,paid_days,method,form,expires_at,params)
    values (p_token,p_user,p_product,p_revision,p_channel,p_hash,p_price,p_unit,p_net,
      v.credits,v.paid_days,p_method,p_form,v_expiry,p_params);
  return public.resume_catalog_checkout(p_user,p_token,p_hash,p_channel);
end
$$;


ALTER FUNCTION "public"."lock_catalog_checkout"("p_user" "uuid", "p_token" "uuid", "p_hash" "text", "p_product" "text", "p_revision" integer, "p_channel" "text", "p_key" "text", "p_price" "text", "p_unit" integer, "p_net" integer, "p_percent" integer, "p_method" "text", "p_form" "text", "p_params" "jsonb", "p_store" "text", "p_mode" "text") OWNER TO "postgres";


