    LANGUAGE "sql"
    SET "search_path" TO ''
    AS $$
  delete from public.identity_refusals r
   where r.id in (select o.id from public.identity_refusals o
                   where o.created_at < now() - interval '90 days'
                   order by o.created_at
                   limit 500)
$$;


