CREATE OR REPLACE FUNCTION "public"."read_template_category_sync_source"("p_keys" "text"[]) RETURNS "jsonb"
    LANGUAGE "sql" STABLE
    SET "search_path" TO ''
    AS $$
  with recursive up(key, parent_id) as (
    select key, parent_id from public.template_categories where key = any(p_keys) and kind = 'template'
    union
    select c.key, c.parent_id from public.template_categories c join up on c.key = up.parent_id
  )
  select coalesce(jsonb_agg(jsonb_build_object(
      'key', c.key, 'parent_id', c.parent_id, 'level', c.level, 'is_system', c.is_system,
      'name_en', c.name_en, 'name_zh', c.name_zh, 'intro_en', c.intro_en, 'intro_zh', c.intro_zh,
      'card_style', c.card_style, 'sort_order', c.sort_order, 'slug', c.slug, 'is_visible', c.is_visible,
      'seo_title_en', c.seo_title_en, 'seo_title_zh', c.seo_title_zh,
      'seo_description_en', c.seo_description_en, 'seo_description_zh', c.seo_description_zh)
    order by c.level, c.sort_order, c.key), '[]'::jsonb)
  from public.template_categories c where c.key in (select key from up)
$$;


ALTER FUNCTION "public"."read_template_category_sync_source"("p_keys" "text"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."read_template_series_sync_source"("p_slug" "text") RETURNS "jsonb"
    LANGUAGE "sql" STABLE
    SET "search_path" TO ''
    AS $$
  select jsonb_build_object(
    'series', jsonb_build_object('slug', s.slug, 'name_en', s.name_en, 'name_zh', s.name_zh,
      'description_en', s.description_en, 'description_zh', s.description_zh, 'cover_url', s.cover_url,
      'category_key', s.category_key, 'sort_order', s.sort_order, 'is_active', s.is_active,
      'show_members', s.show_members),
    'members', coalesce((select jsonb_agg(t.id order by t.series_sort_order, t.id)
      from public.templates t where t.series_id = s.id), '[]'::jsonb),
    'deleted', s.deleted_at is not null)
  from public.template_series s where s.slug = p_slug
$$;


ALTER FUNCTION "public"."read_template_series_sync_source"("p_slug" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."read_template_sync_profiles"("p_id" "text", "p_version" integer) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO ''
    AS $$
declare tp public.template_prompts; v_inactive jsonb;
begin
  select * into tp from public.template_prompts where template_id = p_id;
  if not found or tp.version <> p_version then raise exception 'SOURCE_CHANGED'; end if;
  select coalesce(jsonb_agg(jsonb_build_object('profile',p.profile,'version',v.version,'body',v.body,
      'model_params',v.model_params,'style_refs',v.style_refs,'quality',p.quality,'credits_cost',p.credits_cost,
      'unpriced_resolutions',to_jsonb(p.unpriced_resolutions),
      'provider',case when v.provider_id is null then p.provider_unmatched
        else (select jsonb_build_object('adapter',a.adapter,'model',a.model,'base_url',a.base_url)
              from public.ai_providers a where a.id = v.provider_id) end,
      'provider_missing',v.provider_id is not null and not exists(select from public.ai_providers a where a.id = v.provider_id))
      order by p.profile),'[]'::jsonb) into v_inactive
    from public.template_profiles p join public.template_prompt_versions v on v.template_id = p.template_id and v.version = p.prompt_version
    where p.template_id = p_id and p.profile <> tp.active_profile;
  return jsonb_build_object('active', tp.active_profile, 'inactive', v_inactive);
end;
$$;


ALTER FUNCTION "public"."read_template_sync_profiles"("p_id" "text", "p_version" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."read_template_sync_source"("p_id" "text") RETURNS "jsonb"
    LANGUAGE "sql" STABLE
    SET "search_path" TO ''
    AS $$
  select jsonb_build_object('catalog', admin.template_sync_catalog(),
    'template', to_jsonb(t) - case when t.unpriced_resolutions is null then 'unpriced_resolutions' else '' end,
    'prompt', to_jsonb(p), 'provider', to_jsonb(a))
  from (select tt.id,tt.module,tt.name,tt.description,tt.category_key,tt.subcategory_key,
          s.slug as series_slug,tt.series_sort_order,tt.translations,tt.fields,tt.quality,tt.credits_cost,tt.visible_in,
          tt.cover_before_url,tt.cover_after_url,tt.cover_media_type,tt.cover_video_url,tt.cover_poster_url,tt.cover_locales,
          sale.unpriced_resolutions
          from public.templates tt left join public.template_series s on s.id=tt.series_id
          left join public.template_sale_approvals sale on sale.template_id=tt.id where tt.id=p_id) t
  left join lateral (select body,version,model_params,provider_id from public.template_prompts
    where template_id=t.id) p on true
  left join lateral (select adapter,model,base_url from public.ai_providers
    where id=p.provider_id and module='image') a on true
$$;


