CREATE OR REPLACE FUNCTION "public"."session_identity"() RETURNS TABLE("id" "uuid", "email" "text", "phone" "text", "email_confirmed_at" timestamp with time zone, "phone_confirmed_at" timestamp with time zone, "app_metadata" "jsonb", "user_metadata" "jsonb", "role" "text", "banned_at" timestamp with time zone)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select u.id, u.email::text, u.phone::text, u.email_confirmed_at, u.phone_confirmed_at,
    coalesce(u.raw_app_meta_data, '{}'::jsonb), coalesce(u.raw_user_meta_data, '{}'::jsonb),
    p.role, p.banned_at
  from auth.users u
  -- Primary keys on both sides. A JWT without session_id (never one Auth issues to a user) matches nothing.
  join auth.sessions s on s.id = (auth.jwt() ->> 'session_id')::uuid and s.user_id = u.id
  left join public.profiles p on p.id = u.id
  where u.id = auth.uid()
    and u.deleted_at is null
    and (u.banned_until is null or u.banned_until <= now())
    and (s.not_after is null or s.not_after > now())
$$;


ALTER FUNCTION "public"."session_identity"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."set_job_again_of"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $_$
declare
  v_raw text := new.inputs ->> 'again_of';
  v_source uuid;
begin
  -- Only this trigger sets the column: a value written straight into it is dropped too.
  new.again_of := null;
  if not (new.inputs ? 'again_of') then
    return new;
  end if;
  new.inputs := new.inputs - 'again_of';
  if v_raw ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' then
    select g.id into v_source
      from public.generation_jobs g
     where g.id = v_raw::uuid and g.user_id = new.user_id and g.template_id = new.template_id
       and g.status = 'succeeded' and g.deleted_at is null;
    new.again_of := v_source;
  end if;
  return new;
end;
$_$;


ALTER FUNCTION "public"."set_job_again_of"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."set_job_visibility"("p_job_id" "uuid", "p_user_id" "uuid", "p_visibility" "text") RETURNS "public"."generation_jobs"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_job public.generation_jobs;
begin
  if p_visibility is null or p_visibility not in ('public', 'private') then
    raise exception 'INVALID_INPUT' using detail = 'visibility must be public or private';
  end if;

  select * into v_job from public.generation_jobs
   where id = p_job_id and user_id = p_user_id and deleted_at is null and org_access_ended_at is null
     for update;
  if not found then
    raise exception 'JOB_NOT_FOUND';
  end if;

  -- An org work is gallery-excluded (1941), so it stays private here too.
  if v_job.gallery_excluded then
    if p_visibility = 'public' then
      raise exception 'WORK_PRIVATE_ONLY';
    end if;
    return v_job;
  end if;

  if v_job.credit_pool = 'free' and p_visibility = 'private' then
    raise exception 'FREE_WORK_PUBLIC';
  end if;

  update public.generation_jobs set visibility = p_visibility where id = p_job_id
  returning * into v_job;
  return v_job;
end;
$$;


ALTER FUNCTION "public"."set_job_visibility"("p_job_id" "uuid", "p_user_id" "uuid", "p_visibility" "text") OWNER TO "postgres";


