CREATE OR REPLACE FUNCTION "public"."sms_request_send"("p_phone_key" "text", "p_ip" "inet", "p_ref_slug" "text") RETURNS "text"
    LANGUAGE "sql"
    SET "search_path" TO ''
    AS $$
