CREATE OR REPLACE FUNCTION "public"."start_poster_photo"("p_user_id" "uuid", "p_provider" "text", "p_per_hour" integer) RETURNS TABLE("extraction_id" bigint, "credits" integer)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare
  v_profile public.profiles;
  v_price integer;
  v_pool text;
  v_id bigint;
begin
  select * into v_profile from public.profiles where id = p_user_id for update;
  if not found then raise exception 'PROFILE_NOT_FOUND'; end if;
  if v_profile.banned_at is not null then raise exception 'USER_BANNED'; end if;

  select (s.value #>> '{}')::integer into v_price from public.system_settings s
   where s.key = 'poster_photo_credits' and jsonb_typeof(s.value) = 'number' and (s.value #>> '{}') ~ '^[1-9][0-9]*$';
  if v_price is null then raise exception 'PRICE_UNSET'; end if;

  if (select count(*) from public.poster_extractions e
       where e.user_id = p_user_id and e.created_at >= now() - interval '1 hour') >= p_per_hour then
    raise exception 'RATE_LIMITED';
  end if;

  -- Paid first, then free; org members from org shares only (1897).
  v_pool := public._reserve_pool(v_profile, v_price, 'web', null);

  insert into public.poster_extractions (user_id, source, input_chars, status, provider, credits, credit_pool)
  values (p_user_id, 'photo', 0, 'pending', p_provider, v_price, v_pool)
  returning id into v_id;

  perform public._apply_credit_change(p_user_id, v_pool, 'reserve', -v_price, 'poster photo',
    'poster_photo:' || v_id::text || ':reserve');
  return query select v_id, v_price;
end;
$_$;


ALTER FUNCTION "public"."start_poster_photo"("p_user_id" "uuid", "p_provider" "text", "p_per_hour" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."submit_business_inquiry"("p_inquiry" "jsonb", "p_ip_hash" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $_$
declare
  v_email text := lower(btrim(p_inquiry ->> 'email'));
  v_id uuid;
begin
  if v_email is null or v_email = '' then
    raise exception 'INVALID_INPUT' using detail = 'email is required';
  end if;
  if p_ip_hash is not null and p_ip_hash !~ '^[0-9a-f]{64}$' then
    raise exception 'INVALID_INPUT' using detail = 'ip_hash must be a sha256 hex digest';
  end if;

  if p_ip_hash is not null then
    perform pg_advisory_xact_lock(hashtextextended('inquiry:ip:' || p_ip_hash, 0));
    if (select count(*) from public.business_inquiries b
         where b.ip_hash = p_ip_hash and b.created_at > now() - interval '1 hour') >= 3 then
      return jsonb_build_object('status', 'ip_hourly', 'id', null);
    end if;
    if (select count(*) from public.business_inquiries b
         where b.ip_hash = p_ip_hash and b.created_at > now() - interval '24 hours') >= 10 then
      return jsonb_build_object('status', 'ip_daily', 'id', null);
    end if;
  end if;

  perform pg_advisory_xact_lock(hashtextextended('inquiry:email:' || v_email, 0));
  if (select count(*) from public.business_inquiries b
       where lower(b.email) = v_email and b.created_at > now() - interval '24 hours') >= 3 then
    return jsonb_build_object('status', 'email_daily', 'id', null);
  end if;

  insert into public.business_inquiries (
    locale, page, user_id, name, email, company, monthly_volume, uses, message,
    job_title, website, wechat, phone, team_size, country, platforms, needs, start_time, ip_hash
  ) values (
    p_inquiry ->> 'locale',
    p_inquiry ->> 'page',
    (p_inquiry ->> 'user_id')::uuid,
    p_inquiry ->> 'name',
    v_email,
    p_inquiry ->> 'company',
    p_inquiry ->> 'monthly_volume',
    array(select jsonb_array_elements_text(coalesce(p_inquiry -> 'uses', '[]'::jsonb))),
    p_inquiry ->> 'message',
    p_inquiry ->> 'job_title',
    p_inquiry ->> 'website',
    p_inquiry ->> 'wechat',
    p_inquiry ->> 'phone',
    p_inquiry ->> 'team_size',
    p_inquiry ->> 'country',
    array(select jsonb_array_elements_text(coalesce(p_inquiry -> 'platforms', '[]'::jsonb))),
    array(select jsonb_array_elements_text(coalesce(p_inquiry -> 'needs', '[]'::jsonb))),
    p_inquiry ->> 'start_time',
    p_ip_hash
  )
  returning id into v_id;

  return jsonb_build_object('status', 'ok', 'id', v_id);
end;
$_$;


ALTER FUNCTION "public"."submit_business_inquiry"("p_inquiry" "jsonb", "p_ip_hash" "text") OWNER TO "postgres";


