$$;


ALTER FUNCTION "public"."support_reply_hours"("p_tier" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."sweep_stale_generation_jobs"("p_older_than" interval, "p_limit" integer DEFAULT 50) RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_id uuid;
  refunded integer := 0;
  since timestamptz;
begin
  if p_older_than < interval '10 minutes' then raise exception 'INVALID_INPUT'; end if;
  select (s.value #>> '{}')::timestamptz into since from public.system_settings s where s.key = 'generation_sweep_since';
  if since is not null then
    for v_id in
      select j.id from public.generation_jobs j
       where j.status = 'running' and j.created_at < now() - p_older_than
         and j.created_at >= greatest(since, now() - interval '24 hours')
       order by j.created_at
       limit least(greatest(p_limit, 1), 200)
    loop
      begin
        perform public.refund_job(v_id, 'STALE_TIMEOUT', null, null);
        refunded := refunded + 1;
      exception when others then
        -- Settled meanwhile (JOB_ALREADY_SETTLED) or any other refusal: leave it for the next pass.
        null;
      end;
    end loop;
  end if;
  delete from public.generation_slots s
   where s.acquired_at < now() - interval '10 minutes' and (s.released_at is not null or s.expires_at < now());
  return refunded;
end;
$$;


ALTER FUNCTION "public"."sweep_stale_generation_jobs"("p_older_than" interval, "p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."sync_image_capabilities"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
begin
  if tg_op = 'UPDATE' and (new.adapter,new.base_url,new.model) is distinct from (old.adapter,old.base_url,old.model) then
    if new.capabilities = old.capabilities then
      new.capabilities := '{}';
      new.estimated_image_costs := '{}';
    end if;
  end if;
  if new.adapter = 'openai_images' and new.capabilities = '{}' then
    new.capabilities := jsonb_build_object(
      'resolutions',to_jsonb(new.resolutions),'aspectRatios','["16:9","4:5","1:1","9:16","3:2","4:3","2:3","1:2","1:3"]'::jsonb,
      'originalRatio',true,'minReferences',0,'maxReferences',4,'fetchedAt',now()
    );
  end if;
  if new.capabilities <> '{}' and new.capabilities->'resolutions' is distinct from to_jsonb(new.resolutions) then
    if tg_op = 'UPDATE' and new.capabilities = old.capabilities then
      new.capabilities := case when new.adapter = 'openai_images' then
        jsonb_set(new.capabilities,'{resolutions}',to_jsonb(new.resolutions)) else '{}'::jsonb end;
    else raise exception 'INVALID_PROVIDER_CAPABILITIES' using errcode='23514';
    end if;
  end if;
  return new;
end;
$$;


ALTER FUNCTION "public"."sync_image_capabilities"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."sync_preview_category"("p_category" "jsonb", "p_validate_only" boolean DEFAULT false) RETURNS "text"
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $_$
declare
  k text := p_category->>'key';
  en text := btrim(p_category->>'name_en');
  zh text := btrim(p_category->>'name_zh');
  parent text := nullif(p_category->>'parent_id', '');
  v_position integer := (p_category->>'sort_order')::integer;
  previous public.template_categories;
  v_result text;
begin
  if k is null or k !~ '^[a-z0-9]+(-[a-z0-9]+)*$' or v_position is null then raise exception 'INVALID_SYNC'; end if;
  -- The same exclusive tree lock as admin_save_template_category (分类管理).
  perform pg_advisory_xact_lock(hashtextextended('shotviva.category_tree', 0));
  select * into previous from public.template_categories where key = k for update;
  if previous.key is not null and previous.kind <> 'template' then raise exception 'CATEGORY_KIND_MISMATCH'; end if;
  if previous.is_system or coalesce((p_category->>'is_system')::boolean, false) then
    if previous.key is null then raise exception 'CATEGORY_MISSING'; end if;
    return 'system';
  end if;
  if exists(select 1 from public.template_categories where name_en_lookup = 'template:' || lower(en) and key <> k)
      or exists(select 1 from public.template_categories where name_zh_lookup = 'template:' || zh and key <> k) then
    raise exception 'CATEGORY_NAME_TAKEN';
  end if;
  if previous.key is null then
    if parent is not null and not exists(select 1 from public.template_categories
        where key = parent and kind = 'template' and not is_system and level < 3) then
      raise exception 'CATEGORY_PARENT_MISSING';
    end if;
    insert into public.template_categories(key, name_en, name_zh, intro_en, intro_zh, card_style, sort_order,
        parent_id, slug, is_visible, seo_title_en, seo_title_zh, seo_description_en, seo_description_zh)
      values(k, en, zh, nullif(btrim(p_category->>'intro_en'), ''), nullif(btrim(p_category->>'intro_zh'), ''),
        coalesce(p_category->>'card_style', 'pair'), v_position, parent, coalesce(nullif(p_category->>'slug', ''), k),
        coalesce((p_category->>'is_visible')::boolean, true), nullif(p_category->>'seo_title_en', ''),
        nullif(p_category->>'seo_title_zh', ''), nullif(p_category->>'seo_description_en', ''),
        nullif(p_category->>'seo_description_zh', ''));
    v_result := 'created';
  elsif (previous.name_en, previous.name_zh, previous.sort_order) is distinct from (en, zh, v_position) then
    update public.template_categories set name_en = en, name_zh = zh, sort_order = v_position where key = k;
    v_result := 'updated';
  else
    v_result := 'unchanged';
  end if;
  if p_validate_only then raise exception using errcode = 'Z9301'; end if;
  return v_result;
exception when sqlstate 'Z9301' then return v_result;
end $_$;


ALTER FUNCTION "public"."sync_preview_category"("p_category" "jsonb", "p_validate_only" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."sync_preview_series"("p_series" "jsonb", "p_validate_only" boolean DEFAULT false) RETURNS "text"
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $_$
declare
  v_slug text := p_series->>'slug';
  previous public.template_series;
  saved public.template_series;
  v_result text;
begin
  if v_slug is null or v_slug !~ '^[a-z0-9]+(-[a-z0-9]+)*$' then raise exception 'INVALID_SYNC'; end if;
  perform pg_advisory_xact_lock_shared(hashtextextended('shotviva.category_tree', 0));
  perform pg_advisory_xact_lock(hashtextextended('shotviva.template_series', 0));
  -- check_series_category would refuse it too; this names the reason for the workflow log.
  if not exists(select 1 from public.template_categories
      where key = p_series->>'category_key' and kind = 'template' and not is_system) then
    raise exception 'SERIES_CATEGORY_MISSING';
  end if;
  saved := jsonb_populate_record(null::public.template_series, p_series - 'id');
  select * into previous from public.template_series where slug = v_slug for update;
  if previous.deleted_at is not null then raise exception 'SERIES_DELETED'; end if;
  if previous.id is null then
    insert into public.template_series(slug, name_en, name_zh, description_en, description_zh, cover_url,
        category_key, sort_order, is_active, show_members)
      values(v_slug, saved.name_en, saved.name_zh, saved.description_en, saved.description_zh, saved.cover_url,
        saved.category_key, coalesce(saved.sort_order, 0), false, coalesce(saved.show_members, false));
    v_result := 'created';
  elsif (previous.name_en, previous.name_zh, previous.description_en, previous.description_zh, previous.cover_url,
      previous.category_key, previous.sort_order, previous.show_members)
      is distinct from (saved.name_en, saved.name_zh, saved.description_en, saved.description_zh, saved.cover_url,
      saved.category_key, coalesce(saved.sort_order, 0), coalesce(saved.show_members, false)) then
    update public.template_series set name_en = saved.name_en, name_zh = saved.name_zh,
      description_en = saved.description_en, description_zh = saved.description_zh, cover_url = saved.cover_url,
      category_key = saved.category_key, sort_order = coalesce(saved.sort_order, 0),
      show_members = coalesce(saved.show_members, false)
    where id = previous.id;
    v_result := 'updated';
  else
    v_result := 'unchanged';
  end if;
  if p_validate_only then raise exception using errcode = 'Z9301'; end if;
  return v_result;
exception when sqlstate 'Z9301' then return v_result;
end $_$;


ALTER FUNCTION "public"."sync_preview_series"("p_series" "jsonb", "p_validate_only" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."sync_preview_series_active"("p_actor" "uuid", "p_slug" "text", "p_active" boolean, "p_run_id" "text", "p_validate_only" boolean DEFAULT false) RETURNS "text"
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
declare
  previous public.template_series;
  v_result text := 'unchanged';
begin
  if p_active is null or nullif(p_run_id, '') is null then raise exception 'INVALID_SYNC'; end if;
  if not exists(select from public.profiles where id = p_actor and role = 'admin' and banned_at is null) then
    raise exception 'NOT_ADMIN';
  end if;
  perform pg_advisory_xact_lock_shared(hashtextextended('shotviva.category_tree', 0));
  perform pg_advisory_xact_lock(hashtextextended('shotviva.template_series', 0));
  select * into previous from public.template_series where slug = p_slug for update;
  if previous.id is null then raise exception 'SERIES_MISSING'; end if;
  if previous.deleted_at is not null then raise exception 'SERIES_DELETED'; end if;
  if previous.is_active is distinct from p_active then
    update public.template_series set is_active = p_active where id = previous.id;
    perform admin.template_sync_audit(p_actor, 'series_sync_active', p_slug,
      'T93 sync from preview run ' || p_run_id || case when p_active then ': published' else ': unpublished' end);
    v_result := case when p_active then 'published' else 'unpublished' end;
  end if;
  if p_validate_only then raise exception using errcode = 'Z9301'; end if;
  return v_result;
exception when sqlstate 'Z9301' then return v_result;
end $$;


ALTER FUNCTION "public"."sync_preview_series_active"("p_actor" "uuid", "p_slug" "text", "p_active" boolean, "p_run_id" "text", "p_validate_only" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."sync_preview_series_delete"("p_actor" "uuid", "p_slug" "text", "p_run_id" "text", "p_validate_only" boolean DEFAULT false) RETURNS "jsonb"
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
declare
  previous public.template_series;
  v_moved integer;
  v_result jsonb;
begin
  if nullif(p_run_id, '') is null then raise exception 'INVALID_SYNC'; end if;
  if not exists(select from public.profiles where id = p_actor and role = 'admin' and banned_at is null) then
    raise exception 'NOT_ADMIN';
  end if;
  perform pg_advisory_xact_lock_shared(hashtextextended('shotviva.category_tree', 0));
  perform pg_advisory_xact_lock(hashtextextended('shotviva.template_series', 0));
  select * into previous from public.template_series where slug = p_slug for update;
  if previous.id is null then return jsonb_build_object('result', 'absent', 'moved', 0, 'was_live', false); end if;
  if previous.deleted_at is not null then return jsonb_build_object('result', 'unchanged', 'moved', 0, 'was_live', false); end if;
  perform 1 from public.templates where series_id = previous.id order by id for update;
  update public.templates set series_id = null, series_sort_order = 0 where series_id = previous.id;
  get diagnostics v_moved = row_count;
  update public.template_series set is_active = false, deleted_at = now() where id = previous.id;
  perform admin.template_sync_audit(p_actor, 'series_sync_delete', p_slug,
    format('T93 sync from preview run %s: deleted on the test site, %s templates moved out%s',
      p_run_id, v_moved, case when previous.is_active then ', was published' else '' end));
  v_result := jsonb_build_object('result', 'deleted', 'moved', v_moved, 'was_live', previous.is_active);
  if p_validate_only then raise exception using errcode = 'Z9301'; end if;
  return v_result;
exception when sqlstate 'Z9301' then return v_result;
end $$;


ALTER FUNCTION "public"."sync_preview_series_delete"("p_actor" "uuid", "p_slug" "text", "p_run_id" "text", "p_validate_only" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."sync_preview_series_members"("p_slug" "text", "p_members" "text"[], "p_validate_only" boolean DEFAULT false) RETURNS "jsonb"
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
declare
  v_series uuid;
  v_deleted timestamptz;
  v_placed text[];
  v_result jsonb;
begin
  if p_members is null or cardinality(p_members) <> (select count(distinct m) from unnest(p_members) m) then
    raise exception 'INVALID_SERIES_MEMBERS';
  end if;
  perform pg_advisory_xact_lock_shared(hashtextextended('shotviva.category_tree', 0));
  perform pg_advisory_xact_lock(hashtextextended('shotviva.template_series', 0));
  select id, deleted_at into v_series, v_deleted from public.template_series where slug = p_slug for update;
  if v_series is null then raise exception 'SERIES_MISSING'; end if;
  if v_deleted is not null then raise exception 'SERIES_DELETED'; end if;
  perform 1 from public.templates where id = any(p_members) or series_id = v_series order by id for update;
  select coalesce(array_agg(m.id order by m.ord), '{}') into v_placed
    from unnest(p_members) with ordinality as m(id, ord)
    join public.templates t on t.id = m.id
    join public.template_categories c on c.key = t.category_key
    where not c.is_system and t.id not in ('freeform', 'edit')
      and (t.series_id is null or t.series_id = v_series);
  update public.templates set series_id = null, series_sort_order = 0
    where series_id = v_series and not (id = any(v_placed));
  update public.templates t set series_id = v_series, series_sort_order = m.ord::integer
    from unnest(v_placed) with ordinality as m(id, ord)
    where t.id = m.id and (t.series_id is distinct from v_series or t.series_sort_order <> m.ord);
  v_result := jsonb_build_object('placed', to_jsonb(v_placed),
    'skipped', to_jsonb(array(select m from unnest(p_members) m where not (m = any(v_placed)))));
  if p_validate_only then raise exception using errcode = 'Z9301'; end if;
  return v_result;
exception when sqlstate 'Z9301' then return v_result;
end $$;


ALTER FUNCTION "public"."sync_preview_series_members"("p_slug" "text", "p_members" "text"[], "p_validate_only" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."sync_preview_template"("p_template" "jsonb", "p_prompt" "jsonb", "p_provider" "jsonb", "p_floors" "jsonb", "p_run_id" "text", "p_locales" "text"[], "p_target_token" "text", "p_catalog_version" "text", "p_validate_only" boolean DEFAULT false) RETURNS integer
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
declare
  v_id text := p_template->>'id';
  v_provider uuid;
  v_catalog text;
  v_quote jsonb;
  v_inserted boolean;
  v_template_xmin text;
  v_prompt_xmin text;
  v_previous public.template_prompts;
  v_version integer;
  v_live boolean;
  v_featured smallint;
  -- The sub-category and series (2026-11-12): carried only when the source sends the keys, so a
  -- caller from before this migration keeps the old behaviour (production's own filing stays).
  v_assign boolean := p_template ? 'subcategory_key' and p_template ? 'series_slug';
  v_sub text := nullif(p_template->>'subcategory_key','');
  v_series uuid;
  v_old_series uuid;
  v_order integer := 0;
  -- Style references (1276): carried only when the source sends the key, as for the sub-category.
  v_refs boolean := p_prompt ? 'style_refs';
  v_prompt jsonb;
  v_matches integer;
begin
  -- 3k from a caller still on the old name is read as 4k (PR-2).
  p_template := public.canonical_tiers(p_template);
  p_floors := public.canonical_tiers(p_floors);
  if nullif(p_run_id,'') is null or nullif(btrim(p_prompt->>'body'),'') is null then
    raise exception 'INVALID_SYNC';
  end if;
  if v_refs and jsonb_typeof(p_prompt->'style_refs') is distinct from 'array' then raise exception 'INVALID_STYLE_REFS'; end if;
  -- Serialize dispatches even before the first template row exists.
  -- Same lock and lock order as #385 cutover and rollback. The subsequent read sees a
  -- cutover that won the lock; one that comes later must wait for the entire write.
  perform pg_advisory_xact_lock_shared(hashtextextended('shotviva.template_catalog',0));
  perform pg_advisory_xact_lock(hashtextextended('template-sync:' || v_id, 0));
  select synced_version into v_version from public.template_sync_history
    where template_id = v_id and run_id = p_run_id;
  if found then return v_version; end if;
  v_catalog := admin.template_sync_catalog();
  if v_catalog not in ('v1','v2') or p_catalog_version is distinct from v_catalog
      or coalesce(p_floors->>'version','v1') <> v_catalog then raise exception 'CATALOG_MISMATCH'; end if;
  -- The tree lock before any category row (1272): 分类管理 takes the tree lock exclusively and then
  -- writes rows, so a row share taken first could wait on it while it waits on us. Same order as
  -- admin_save_template_assignment and the 1270–1271 sync: tree shared, series, then rows.
  perform pg_advisory_xact_lock_shared(hashtextextended('shotviva.category_tree',0));
  if v_assign then perform pg_advisory_xact_lock(hashtextextended('shotviva.template_series',0)); end if;
  perform 1 from public.template_categories where key = p_template->>'category_key' for share;
  if not found then raise exception 'CATEGORY_MISSING'; end if;
  if v_assign then
    if v_sub is not null then
      perform 1 from public.template_category_paths p join public.template_categories c on c.key = p.key
        where p.key = v_sub and p.root_key = p_template->>'category_key' and p.key <> p.root_key and not c.is_system;
      if not found then raise exception 'SUBCATEGORY_MISSING'; end if;
      perform 1 from public.template_categories where key = v_sub for share;
    end if;
    if nullif(p_template->>'series_slug','') is not null then
      select id into v_series from public.template_series where slug = p_template->>'series_slug' for share;
      if not found then raise exception 'SERIES_MISSING'; end if;
    end if;
  end if;

  if p_provider is not null and p_provider <> 'null'::jsonb then
    -- The one production row with this adapter, model and endpoint; of several (a leftover copy),
    -- the module's active one (at most one per module). Otherwise say which case it is (1277).
    select count(*) into v_matches from public.ai_providers
      where module = 'image' and adapter = p_provider->>'adapter'
        and model = p_provider->>'model' and base_url = p_provider->>'base_url';
    if v_matches = 0 then raise exception 'PROVIDER_MISSING'; end if;
    begin
      select id into strict v_provider from public.ai_providers
        where module = 'image' and adapter = p_provider->>'adapter'
          and model = p_provider->>'model' and base_url = p_provider->>'base_url'
          and (v_matches = 1 or is_active) for share;
    exception when no_data_found or too_many_rows then
      raise exception 'PROVIDER_NOT_UNIQUE' using detail = format(
        '%s rows share this adapter, model and endpoint and none is the active provider', v_matches);
    end;
  end if;
  -- The editor RPC resolves the effective provider and checks its floor and exact tariff.
  -- Refuse incomplete input: the editor's comparison with a missing numeric tier is SQL NULL.
  if jsonb_typeof(p_floors->'providers') is distinct from 'object' or exists (
    select from jsonb_each(p_floors->'providers') f cross join unnest(array['1k','2k','4k']) r
      where jsonb_typeof(f.value->(p_template->>'quality')->r) is distinct from 'number'
         or (f.value->(p_template->>'quality')->>r)::numeric < 1
  ) then raise exception 'MODEL_CHANGED'; end if;

  -- Acquire the same row lock as normal editor saves, including racing first-time inserts.
  insert into public.templates (id, name, category_key, credits_cost, sort_order)
    values (v_id, p_template->>'name', p_template->>'category_key', p_template->'credits_cost',
      (select coalesce(max(sort_order),0) + 10 from public.templates))
    on conflict (id) do nothing returning true into v_inserted;
  select xmin::text, is_active, featured_rank into strict v_template_xmin, v_live, v_featured from public.templates where id = v_id for update;
  select tp.xmin::text into v_prompt_xmin from public.template_prompts tp where template_id=v_id for update;
  if p_target_token is distinct from (case when v_inserted then 'missing'
      else v_template_xmin || '/' || coalesce(v_prompt_xmin,'-') end) then raise exception 'STALE_TARGET'; end if;
  if v_featured is not null and not (p_template->'visible_in' ? 'web') then raise exception 'FEATURED_WEB_REQUIRED'; end if;
  if v_live and p_template->'visible_in' ? 'web' and
      (nullif(btrim(p_template->>'description'),'') is null or not public._template_has_cover_parts(
        p_template->>'cover_before_url', p_template->>'cover_after_url', p_template->'cover_locales', p_locales))
    then raise exception 'LIVE_TEMPLATE_INCOMPLETE'; end if;

  select tp.* into v_previous from public.template_prompts tp where template_id = v_id;
  -- Keep publication, feature rank and sort order under production control. The normal editor
  -- RPC also enforces production's model constraints when the T96 migration is present.
  -- With style references, the editor's three-argument writer: the same 0940 trigger checks the
  -- keys (this template's private prefix, at most three, no repeats) and the same 0941/0943 checks
  -- the model's input range with production's model; an unchanged list keeps the version. Without
  -- the key, the two-argument writer keeps production's own references, as before.
  v_prompt := (p_prompt - array['provider_id','style_refs']) || jsonb_build_object('provider_id',v_provider);
  if v_refs then
    perform public.admin_upsert_template(
      (p_template - array['sort_order','is_active','featured_rank','category','price_floors',
        'subcategory_key','series_slug','series_sort_order'])
        || jsonb_build_object('price_floors',p_floors),
      v_prompt, p_prompt->'style_refs');
  else
    perform public.admin_upsert_template(
      (p_template - array['sort_order','is_active','featured_rank','category','price_floors',
        'subcategory_key','series_slug','series_sort_order'])
        || jsonb_build_object('price_floors',p_floors),
      v_prompt);
  end if;
  -- The editor writer now holds the effective model lock. Compare the exact response used
  -- by its calculator with the current inputs (including p95, approved tariffs and unit).
  -- A quote changed between the last HTTP read and this transaction rolls back the upsert.
  if nullif(p_floors->>'env_model','') is null or jsonb_typeof(p_floors->'quote_receipt') is distinct from 'object' then
    raise exception 'PRICE_QUOTE_CHANGED';
  end if;
  v_quote := public.template_sync_pricing_input(p_floors->>'env_model')->'receipt';
  if admin.template_sync_quote(v_quote,v_provider,v_id='edit') is distinct from
     admin.template_sync_quote(p_floors->'quote_receipt',v_provider,v_id='edit') then
    raise exception 'PRICE_QUOTE_CHANGED';
  end if;
  -- Production files the template where the test site does: same sub-category, same series (by
  -- slug), none when the test site has none. Series order as the editor keeps it: unchanged while
  -- the series is, appended at the end of a series it joins.
  if v_assign then
    select series_id, coalesce(series_sort_order,0) into v_old_series, v_order from public.templates where id = v_id;
    if v_series is null then v_order := 0;
    elsif v_series is distinct from v_old_series then
      select coalesce(max(series_sort_order),0) + 1 into v_order from public.templates where series_id = v_series;
    end if;
    update public.templates set subcategory_key = v_sub, series_id = v_series, series_sort_order = v_order
      where id = v_id and (subcategory_key, series_id, series_sort_order) is distinct from (v_sub, v_series, v_order);
  end if;
  update public.templates set cover_media_type = p_template->>'cover_media_type',
    cover_video_url = p_template->>'cover_video_url', cover_poster_url = p_template->>'cover_poster_url',
    cover_locales = p_template->'cover_locales' where id = v_id;

  update public.template_prompts set version = version + 1
    where template_id = v_id and version = v_previous.version;
  select version into strict v_version from public.template_prompts where template_id = v_id;
  insert into public.template_sync_history(template_id, run_id, source_version, synced_version,
      previous_version, previous_body, previous_model_params, previous_provider_id, previous_style_refs)
    values (v_id, p_run_id, (p_prompt->>'version')::int, v_version,
      v_previous.version, v_previous.body, v_previous.model_params, v_previous.provider_id, v_previous.style_refs);
  -- The same constraints and T96 RPC are exercised before publishing any cover bytes.
  -- This private SQLSTATE rolls back all changes inside the function's exception block.
  if p_validate_only then raise exception using errcode = 'Z9301'; end if;
  return v_version;
exception when sqlstate 'Z9301' then return v_version;
end;
$$;


ALTER FUNCTION "public"."sync_preview_template"("p_template" "jsonb", "p_prompt" "jsonb", "p_provider" "jsonb", "p_floors" "jsonb", "p_run_id" "text", "p_locales" "text"[], "p_target_token" "text", "p_catalog_version" "text", "p_validate_only" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."sync_preview_template"("p_template" "jsonb", "p_prompt" "jsonb", "p_provider" "jsonb", "p_floors" "jsonb", "p_run_id" "text", "p_locales" "text"[], "p_target_token" "text", "p_catalog_version" "text", "p_profiles" "jsonb", "p_validate_only" boolean DEFAULT false) RETURNS integer
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
declare
  v_id text := p_template->>'id';
  v_provider uuid;
  v_catalog text;
  v_quote jsonb;
  v_inserted boolean;
  v_template_xmin text;
  v_prompt_xmin text;
  v_previous public.template_prompts;
  v_version integer;
  v_live boolean;
  v_featured smallint;
  -- The sub-category and series (2026-11-12): carried only when the source sends the keys, so a
  -- caller from before this migration keeps the old behaviour (production's own filing stays).
  v_assign boolean := p_template ? 'subcategory_key' and p_template ? 'series_slug';
  v_sub text := nullif(p_template->>'subcategory_key','');
  v_series uuid;
  v_old_series uuid;
  v_order integer := 0;
  -- Style references (1276): carried only when the source sends the key, as for the sub-category.
  v_refs boolean := p_prompt ? 'style_refs';
  v_prompt jsonb;
  v_matches integer;
  -- Provider profiles (1443): carried only when the source sends them.
  v_active_profile text := p_profiles->>'active';
  v_entry jsonb;
begin
  -- 3k from a caller still on the old name is read as 4k (PR-2).
  p_template := public.canonical_tiers(p_template);
  p_floors := public.canonical_tiers(p_floors);
  p_profiles := public.canonical_tiers(p_profiles);
  if p_profiles is null or (v_active_profile is null or v_active_profile not in ('openai','seedream')
      or jsonb_typeof(coalesce(p_profiles->'inactive','[]'::jsonb)) <> 'array'
      or jsonb_array_length(coalesce(p_profiles->'inactive','[]'::jsonb)) > 1) then
    raise exception 'INVALID_SYNC';
  end if;
  if nullif(p_run_id,'') is null or nullif(btrim(p_prompt->>'body'),'') is null then
    raise exception 'INVALID_SYNC';
  end if;
  if v_refs and jsonb_typeof(p_prompt->'style_refs') is distinct from 'array' then raise exception 'INVALID_STYLE_REFS'; end if;
  -- Serialize dispatches even before the first template row exists.
  -- Same lock and lock order as #385 cutover and rollback. The subsequent read sees a
  -- cutover that won the lock; one that comes later must wait for the entire write.
  perform pg_advisory_xact_lock_shared(hashtextextended('shotviva.template_catalog',0));
  perform pg_advisory_xact_lock(hashtextextended('template-sync:' || v_id, 0));
  select synced_version into v_version from public.template_sync_history
    where template_id = v_id and run_id = p_run_id;
  if found then return v_version; end if;
  v_catalog := admin.template_sync_catalog();
  if v_catalog not in ('v1','v2') or p_catalog_version is distinct from v_catalog
      or coalesce(p_floors->>'version','v1') <> v_catalog then raise exception 'CATALOG_MISMATCH'; end if;
  -- The tree lock before any category row (1272): 分类管理 takes the tree lock exclusively and then
  -- writes rows, so a row share taken first could wait on it while it waits on us. Same order as
  -- admin_save_template_assignment and the 1270–1271 sync: tree shared, series, then rows.
  perform pg_advisory_xact_lock_shared(hashtextextended('shotviva.category_tree',0));
  if v_assign then perform pg_advisory_xact_lock(hashtextextended('shotviva.template_series',0)); end if;
  perform 1 from public.template_categories where key = p_template->>'category_key' for share;
  if not found then raise exception 'CATEGORY_MISSING'; end if;
  if v_assign then
    if v_sub is not null then
      perform 1 from public.template_category_paths p join public.template_categories c on c.key = p.key
        where p.key = v_sub and p.root_key = p_template->>'category_key' and p.key <> p.root_key and not c.is_system;
      if not found then raise exception 'SUBCATEGORY_MISSING'; end if;
      perform 1 from public.template_categories where key = v_sub for share;
    end if;
    if nullif(p_template->>'series_slug','') is not null then
      select id into v_series from public.template_series where slug = p_template->>'series_slug' for share;
      if not found then raise exception 'SERIES_MISSING'; end if;
    end if;
  end if;

  if p_provider is not null and p_provider <> 'null'::jsonb then
    -- The one production row with this adapter, model and endpoint; of several (a leftover copy),
    -- the module's active one (at most one per module). Otherwise say which case it is (1277).
    select count(*) into v_matches from public.ai_providers
      where module = 'image' and adapter = p_provider->>'adapter'
        and model = p_provider->>'model' and base_url = p_provider->>'base_url';
    if v_matches = 0 then raise exception 'PROVIDER_MISSING'; end if;
    begin
      select id into strict v_provider from public.ai_providers
        where module = 'image' and adapter = p_provider->>'adapter'
          and model = p_provider->>'model' and base_url = p_provider->>'base_url'
          and (v_matches = 1 or is_active) for share;
    exception when no_data_found or too_many_rows then
      raise exception 'PROVIDER_NOT_UNIQUE' using detail = format(
        '%s rows share this adapter, model and endpoint and none is the active provider', v_matches);
    end;
  end if;
  -- The editor RPC resolves the effective provider and checks its floor and exact tariff.
  -- Refuse incomplete input: the editor's comparison with a missing numeric tier is SQL NULL.
  if jsonb_typeof(p_floors->'providers') is distinct from 'object' or exists (
    select from jsonb_each(p_floors->'providers') f cross join unnest(array['1k','2k','4k']) r
      where jsonb_typeof(f.value->(p_template->>'quality')->r) is distinct from 'number'
         or (f.value->(p_template->>'quality')->>r)::numeric < 1
  ) then raise exception 'MODEL_CHANGED'; end if;

  -- Acquire the same row lock as normal editor saves, including racing first-time inserts.
  insert into public.templates (id, name, category_key, credits_cost, sort_order)
    values (v_id, p_template->>'name', p_template->>'category_key', p_template->'credits_cost',
      (select coalesce(max(sort_order),0) + 10 from public.templates))
    on conflict (id) do nothing returning true into v_inserted;
  select xmin::text, is_active, featured_rank into strict v_template_xmin, v_live, v_featured from public.templates where id = v_id for update;
  select tp.xmin::text into v_prompt_xmin from public.template_prompts tp where template_id=v_id for update;
  if p_target_token is distinct from (case when v_inserted then 'missing'
      else v_template_xmin || '/' || coalesce(v_prompt_xmin,'-') end) then raise exception 'STALE_TARGET'; end if;
  if v_featured is not null and not (p_template->'visible_in' ? 'web') then raise exception 'FEATURED_WEB_REQUIRED'; end if;
  if v_live and p_template->'visible_in' ? 'web' and
      (nullif(btrim(p_template->>'description'),'') is null or not public._template_has_cover_parts(
        p_template->>'cover_before_url', p_template->>'cover_after_url', p_template->'cover_locales', p_locales))
    then raise exception 'LIVE_TEMPLATE_INCOMPLETE'; end if;

  select tp.* into v_previous from public.template_prompts tp where template_id = v_id;
  -- Keep publication, feature rank and sort order under production control. The normal editor
  -- RPC also enforces production's model constraints when the T96 migration is present.
  -- With style references, the editor's three-argument writer: the same 0940 trigger checks the
  -- keys (this template's private prefix, at most three, no repeats) and the same 0941/0943 checks
  -- the model's input range with production's model; an unchanged list keeps the version. Without
  -- the key, the two-argument writer keeps production's own references, as before.
  v_prompt := (p_prompt - array['provider_id','style_refs']) || jsonb_build_object('provider_id',v_provider);
  -- The test site's live profile becomes production's (an emergency switch on production is undone
  -- here). Its previous live profile already sits in its own row; the write below fills this one.
  if v_active_profile is not null then
    update public.template_prompts set active_profile = v_active_profile
      where template_id = v_id and active_profile <> v_active_profile;
  end if;
  if v_refs then
    perform public.admin_upsert_template(
      (p_template - array['sort_order','is_active','featured_rank','category','price_floors',
        'subcategory_key','series_slug','series_sort_order'])
        || jsonb_build_object('price_floors',p_floors),
      v_prompt, p_prompt->'style_refs');
  else
    perform public.admin_upsert_template(
      (p_template - array['sort_order','is_active','featured_rank','category','price_floors',
        'subcategory_key','series_slug','series_sort_order'])
        || jsonb_build_object('price_floors',p_floors),
      v_prompt);
  end if;
  -- The editor writer now holds the effective model lock. Compare the exact response used
  -- by its calculator with the current inputs (including p95, approved tariffs and unit).
  -- A quote changed between the last HTTP read and this transaction rolls back the upsert.
  if nullif(p_floors->>'env_model','') is null or jsonb_typeof(p_floors->'quote_receipt') is distinct from 'object' then
    raise exception 'PRICE_QUOTE_CHANGED';
  end if;
  v_quote := public.template_sync_pricing_input(p_floors->>'env_model')->'receipt';
  if admin.template_sync_quote(v_quote,v_provider,v_id='edit') is distinct from
     admin.template_sync_quote(p_floors->'quote_receipt',v_provider,v_id='edit') then
    raise exception 'PRICE_QUOTE_CHANGED';
  end if;
  -- Production files the template where the test site does: same sub-category, same series (by
  -- slug), none when the test site has none. Series order as the editor keeps it: unchanged while
  -- the series is, appended at the end of a series it joins.
  if v_assign then
    select series_id, coalesce(series_sort_order,0) into v_old_series, v_order from public.templates where id = v_id;
    if v_series is null then v_order := 0;
    elsif v_series is distinct from v_old_series then
      select coalesce(max(series_sort_order),0) + 1 into v_order from public.templates where series_id = v_series;
    end if;
    update public.templates set subcategory_key = v_sub, series_id = v_series, series_sort_order = v_order
      where id = v_id and (subcategory_key, series_id, series_sort_order) is distinct from (v_sub, v_series, v_order);
  end if;
  update public.templates set cover_media_type = p_template->>'cover_media_type',
    cover_video_url = p_template->>'cover_video_url', cover_poster_url = p_template->>'cover_poster_url',
    cover_locales = p_template->'cover_locales' where id = v_id;

  update public.template_prompts set version = version + 1
    where template_id = v_id and version = v_previous.version;
  select version into strict v_version from public.template_prompts where template_id = v_id;
  if v_active_profile is not null then
    -- A first sync of a new template inserted the prompt with the default profile.
    update public.template_prompts set active_profile = v_active_profile
      where template_id = v_id and active_profile <> v_active_profile;
    for v_entry in select value from jsonb_array_elements(coalesce(p_profiles->'inactive','[]'::jsonb)) loop
      perform admin.write_synced_profile(v_id, v_active_profile, v_entry);
    end loop;
  end if;
  insert into public.template_sync_history(template_id, run_id, source_version, synced_version,
      previous_version, previous_body, previous_model_params, previous_provider_id, previous_style_refs)
    values (v_id, p_run_id, (p_prompt->>'version')::int, v_version,
      v_previous.version, v_previous.body, v_previous.model_params, v_previous.provider_id, v_previous.style_refs);
  -- The same constraints and T96 RPC are exercised before publishing any cover bytes.
  -- This private SQLSTATE rolls back all changes inside the function's exception block.
  if p_validate_only then raise exception using errcode = 'Z9301'; end if;
  return v_version;
exception when sqlstate 'Z9301' then return v_version;
end;
$$;


ALTER FUNCTION "public"."sync_preview_template"("p_template" "jsonb", "p_prompt" "jsonb", "p_provider" "jsonb", "p_floors" "jsonb", "p_run_id" "text", "p_locales" "text"[], "p_target_token" "text", "p_catalog_version" "text", "p_profiles" "jsonb", "p_validate_only" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."sync_preview_template_state"("p_actor" "uuid", "p_id" "text", "p_sale" boolean, "p_active" boolean, "p_run_id" "text", "p_locales" "text"[], "p_validate_only" boolean DEFAULT false) RETURNS "jsonb"
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
declare
  t public.templates;
  v_sale boolean;
  v_reason text := 'T93 sync from preview run ' || p_run_id;
  v_result jsonb := jsonb_build_object('sale', 'unchanged', 'active', 'unchanged');
begin
  if p_sale is null or p_active is null or nullif(p_run_id, '') is null or (p_active and not p_sale) then
    raise exception 'INVALID_SYNC';
  end if;
  if not exists(select from public.profiles where id = p_actor and role = 'admin' and banned_at is null) then
    raise exception 'NOT_ADMIN';
  end if;
  select * into t from public.templates where id = p_id for update;
  if not found then raise exception 'TEMPLATE_MISSING'; end if;
  v_sale := exists(select from public.template_sale_approvals where template_id = p_id and enabled);
  if t.is_active and not p_active then
    update public.templates set is_active = false, featured_rank = null where id = p_id;
    perform admin.template_sync_audit(p_actor, 'template_sync_active', p_id, v_reason || ': unpublished');
    v_result := v_result || jsonb_build_object('active', 'unpublished');
    t.is_active := false;
  end if;
  if v_sale is distinct from p_sale then
    perform public.admin_set_template_sale(p_actor, p_id, p_sale);
    perform admin.template_sync_audit(p_actor, 'template_sync_sale', p_id, v_reason || case when p_sale then ': sale opened' else ': sale closed' end);
    v_result := v_result || jsonb_build_object('sale', case when p_sale then 'opened' else 'closed' end);
  end if;
  if p_active and not t.is_active then
    if 'web' = any(t.visible_in) and (nullif(btrim(t.description), '') is null or not public._template_has_cover_parts(
        t.cover_before_url, t.cover_after_url, t.cover_locales, p_locales)) then
      raise exception 'LIVE_TEMPLATE_INCOMPLETE';
    end if;
    update public.templates set is_active = true where id = p_id;
    set constraints all immediate;
    if 'web' = any(t.visible_in) and not admin.web_standard_sale_allowed(p_id) then
      raise exception 'SALE_ROUTE_NOT_ALLOWED';
    end if;
    perform admin.template_sync_audit(p_actor, 'template_sync_active', p_id, v_reason || ': published');
    v_result := v_result || jsonb_build_object('active', 'published');
  end if;
  if p_validate_only then raise exception using errcode = 'Z9301'; end if;
  return v_result;
exception when sqlstate 'Z9301' then return v_result;
end $$;


ALTER FUNCTION "public"."sync_preview_template_state"("p_actor" "uuid", "p_id" "text", "p_sale" boolean, "p_active" boolean, "p_run_id" "text", "p_locales" "text"[], "p_validate_only" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."sync_subscription"("p_subscription_id" "text", "p_status" "text", "p_current_period_end" timestamp with time zone, "p_cancel_at_period_end" boolean) RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  if p_subscription_id is null or p_status is null or p_current_period_end is null or p_cancel_at_period_end is null then
    raise exception 'INVALID_INPUT' using detail = 'subscription fields are all required';
  end if;

  update public.subscriptions
     set status = p_status,
         current_period_end = p_current_period_end,
         cancel_at_period_end = p_cancel_at_period_end,
         updated_at = now()
   where stripe_subscription_id = p_subscription_id;
  return found;
end;
$$;


ALTER FUNCTION "public"."sync_subscription"("p_subscription_id" "text", "p_status" "text", "p_current_period_end" timestamp with time zone, "p_cancel_at_period_end" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."sync_waffo_subscription"("p_user_id" "uuid", "p_order_id" "text", "p_product_id" "text", "p_status" "text", "p_current_period_end" timestamp with time zone, "p_cancel_at_period_end" boolean, "p_event_at" timestamp with time zone) RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_row public.subscriptions;
begin
  if p_user_id is null or p_order_id is null or p_product_id is null or p_status is null
     or p_cancel_at_period_end is null or p_event_at is null then
    raise exception 'INVALID_INPUT' using detail = 'subscription fields are all required';
  end if;
  if p_status not in ('active', 'past_due', 'canceled') then
    raise exception 'INVALID_INPUT' using detail = 'unknown waffo mirror status';
  end if;

  select * into v_row from public.subscriptions where waffo_order_id = p_order_id for update;

  if not found then
    if p_current_period_end is null then
      raise exception 'INVALID_INPUT' using detail = 'a new waffo subscription needs its period end';
    end if;
    insert into public.subscriptions
      (provider, waffo_order_id, user_id, product_id, status, current_period_end, cancel_at_period_end, last_event_at)
    values
      ('waffo', p_order_id, p_user_id, p_product_id, p_status, p_current_period_end, p_cancel_at_period_end, p_event_at);
    return true;
  end if;

  if v_row.user_id <> p_user_id or v_row.product_id <> p_product_id then
    raise exception 'IDEMPOTENCY_CONFLICT' using detail = 'subscription belongs to another user or product';
  end if;
  if v_row.status = 'canceled' or (v_row.last_event_at is not null and p_event_at < v_row.last_event_at) then
    return false;
  end if;

  update public.subscriptions
     set status = p_status,
         current_period_end = coalesce(p_current_period_end, current_period_end),
         cancel_at_period_end = p_cancel_at_period_end,
         last_event_at = p_event_at,
         updated_at = now()
   where id = v_row.id;
  return true;
end;
$$;


ALTER FUNCTION "public"."sync_waffo_subscription"("p_user_id" "uuid", "p_order_id" "text", "p_product_id" "text", "p_status" "text", "p_current_period_end" timestamp with time zone, "p_cancel_at_period_end" boolean, "p_event_at" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."template_categories"("public"."templates") RETURNS SETOF "public"."template_categories"
    LANGUAGE "sql" STABLE ROWS 1
    SET "search_path" TO ''
    AS $_$
  select c.* from public.template_categories c where c.key=$1.category_key
$_$;


ALTER FUNCTION "public"."template_categories"("public"."templates") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."template_categories_sync_name"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
begin
  update public.templates set category = new.name_en where category_key = new.key and category <> new.name_en;
  return null;
end;
$$;


ALTER FUNCTION "public"."template_categories_sync_name"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."template_category_for"("p_value" "text") RETURNS "text"
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
declare
  v_value text := btrim(coalesce(p_value, ''));
  v_key text;
  v_base text;
  v_name_en text;
  v_name_zh text;
  v_n integer;
begin
  if v_value = '' then
    return null;
  end if;
  select c.key into v_key
  from public.template_categories c
  where (c.kind='template' and c.key=v_value) or c.name_en_lookup='template:'||lower(v_value) or c.name_zh_lookup='template:'||v_value
  order by (c.key = v_value) desc, c.sort_order
  limit 1;
  if v_key is not null then
    return v_key;
  end if;

  v_base := rtrim(left(btrim(regexp_replace(lower(v_value), '[^a-z0-9]+', '-', 'g'), '-'), 36), '-');
  if v_base = '' then
    v_base := 'category';
  end if;
  v_key := v_base;
  v_n := 1;
  while exists (select 1 from public.template_categories c where c.key = v_key) loop
    v_n := v_n + 1;
    v_key := v_base || '-' || v_n;
  end loop;

  v_name_en := btrim(left(v_value, 32));
  v_n := 1;
  while exists (select 1 from public.template_categories c where c.name_en_lookup='template:'||lower(v_name_en)) loop
    v_n := v_n + 1;
    v_name_en := btrim(left(v_value, 32 - length(' ' || v_n))) || ' ' || v_n;
  end loop;
  v_name_zh := btrim(left(v_value, 12));
  v_n := 1;
  while exists (select 1 from public.template_categories c where c.name_zh_lookup='template:'||v_name_zh) loop
    v_n := v_n + 1;
    v_name_zh := btrim(left(v_value, 12 - length(' ' || v_n))) || ' ' || v_n;
  end loop;

  insert into public.template_categories (key, name_en, name_zh, card_style, sort_order)
  values (
    v_key, v_name_en, v_name_zh, 'pair',
    (select coalesce(max(c.sort_order), 0) + 10 from public.template_categories c where c.kind='template' and not c.is_system)
  );
  return v_key;
end;
$$;


ALTER FUNCTION "public"."template_category_for"("p_value" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."template_favorites_guard"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  perform 1 from public.profiles where id = new.user_id for update;
  if not found then
    raise exception 'PROFILE_NOT_FOUND';
  end if;

  if exists (
    select 1 from public.template_favorites f
     where f.user_id = new.user_id and f.template_id = new.template_id
  ) then
    return new;
  end if;

  if not exists (
    select 1 from public.templates t
     where t.id = new.template_id and t.is_active and 'web' = any (t.visible_in)
  ) then
    raise exception 'TEMPLATE_NOT_FOUND';
  end if;

  if (select count(*) from public.template_favorites f where f.user_id = new.user_id) >= 200 then
    raise exception 'FAVORITES_LIMIT';
  end if;

  return new;
end;
$$;


