    "id" bigint NOT NULL,
    "payment_id" bigint NOT NULL,
    "affiliate_user_id" "uuid" NOT NULL,
    "level" smallint NOT NULL,
    "product_id" "text" NOT NULL,
    "rate_bp" integer NOT NULL,
    "base_usd" bigint NOT NULL,
