CREATE OR REPLACE VIEW "admin"."template_tariffs_v2" AS
 SELECT "id",
    'medium'::"text" AS "quality",
        CASE
            WHEN ("id" = 'edit'::"text") THEN '{"1k": 15, "2k": 15, "4k": 58}'::"jsonb"
            WHEN ("id" = 'white-background'::"text") THEN '{"1k": 20, "2k": 20, "4k": 35}'::"jsonb"
            WHEN ("id" = ANY (ARRAY['promo-poster'::"text", 'pet-studio'::"text", 'freeform'::"text"])) THEN '{"1k": 45, "2k": 120, "4k": 190}'::"jsonb"
            ELSE '{"1k": 74, "2k": 150, "4k": 225}'::"jsonb"
        END AS "costs",
    false AS "style_sale_approved"
   FROM "unnest"(ARRAY['dark-dining'::"text", 'delivery-menu'::"text", 'white-background'::"text", 'lifestyle-table'::"text", 'spa-podium'::"text", 'promo-poster'::"text", 'pet-studio'::"text", 'freeform'::"text", 'edit'::"text"]) "id"("id");


ALTER VIEW "admin"."template_tariffs_v2" OWNER TO "postgres";


CREATE OR REPLACE VIEW "admin"."users_overview" AS
 SELECT "u"."id",
    ("u"."email")::"text" AS "email",
    "u"."created_at",
    COALESCE(( SELECT "string_agg"("provider"."value", ', '::"text" ORDER BY "provider"."value") AS "string_agg"
           FROM "jsonb_array_elements_text"(COALESCE(("u"."raw_app_meta_data" -> 'providers'::"text"), '[]'::"jsonb")) "provider"("value")), ("u"."raw_app_meta_data" ->> 'provider'::"text")) AS "provider",
    "p"."role",
    "p"."credits",
    "p"."free_credits",
    "p"."paid_until",
    COALESCE("j"."generation_count", 0) AS "generation_count",
    "j"."last_generation_at",
    "p"."banned_at",
    NULLIF("u"."phone", ''::"text") AS "phone"
   FROM (("auth"."users" "u"
     LEFT JOIN "public"."profiles" "p" ON (("p"."id" = "u"."id")))
     LEFT JOIN LATERAL ( SELECT ("count"(*))::integer AS "generation_count",
            "max"("g"."created_at") AS "last_generation_at"
           FROM "public"."generation_jobs" "g"
          WHERE ("g"."user_id" = "u"."id")) "j" ON (true));


ALTER VIEW "admin"."users_overview" OWNER TO "postgres";


COMMENT ON VIEW "admin"."users_overview" IS 'Owner support view (ARCHITECTURE §10): search by email or phone; credits = paid pool, free_credits = free pool.';



